-- seed.sql — ICB4 framework seed data
-- Generated from data/seed/icb4-framework.json (verified by the T0 extractor).
-- Safe to run in the Supabase SQL Editor AFTER 0001_init.sql and 0002_rls.sql.
-- Re-running is blocked by the unique (name, version) constraint on framework;
-- to reseed, first: delete from public.framework where name='IPMA ICB4';

begin;

-- rating scale (APM 0-5) --------------------------------------------------
insert into public.scale (name, axis) values ('APM Competence Framework 3rd Edition', 'Application');

insert into public.scale_level (scale_id, level, label, knowledge, application, kib_gloss)
select s.id, v.level, v.label, v.knowledge, v.application, v.gloss
from public.scale s,
(values
  (0, 'Unaware', 'Has no awareness of the knowledge needed for the competence.', 'No awareness and no application required at this level.', 'I have no real awareness of this yet.'),
  (1, 'Aware', 'Has an awareness of the knowledge needed for the competence.', 'As only awareness is required at this level, no application is expected.', 'I know it exists and understand the idea, but I haven’t really applied it.'),
  (2, 'Practised', 'Has a working knowledge of, and can describe, the competence.', 'Applies the competence under supervision, primarily in non-complex situations.', 'I can do this, but I still need guidance — mostly on straightforward projects.'),
  (3, 'Competent', 'Has a comprehensive knowledge of the competence in situations of limited complexity.', 'Applies the competence independently, primarily in situations of limited complexity.', 'I do this on my own, on projects of limited complexity.'),
  (4, 'Proficient', 'Has a detailed knowledge of the competence in complex situations and can critically evaluate and adapt as required.', 'Applies the competence independently, primarily in complex situations. Supervises others applying the competence.', 'I do this confidently on complex projects, and I coach others.'),
  (5, 'Expert', 'Has an in-depth knowledge of the competence in complex situations. Can critically evaluate, adapt or develop new theories and/or methods if required and educate others.', 'Applies the competence independently, primarily in complex situations. Recognised as an expert by other senior professionals, who is called on by others for advice on the competence.', 'I’m the person others come to; I adapt and improve how it’s done.')
) as v(level, label, knowledge, application, gloss)
where s.name = 'APM Competence Framework 3rd Edition';

-- framework ---------------------------------------------------------------
insert into public.framework (name, version, scale_id)
select 'IPMA ICB4', 'v4.0.1', s.id from public.scale s where s.name = 'APM Competence Framework 3rd Edition';

-- areas -------------------------------------------------------------------
insert into public.competence_area (framework_id, code, name, sort_order)
select f.id, v.code, v.name, v.sort
from public.framework f, (values
  ('perspective', 'Perspective', 0),
  ('people', 'People', 1),
  ('practice', 'Practice', 2)
) as v(code, name, sort)
where f.name = 'IPMA ICB4' and f.version = 'v4.0.1';

-- competence elements ------------------------------------------------------
-- target_level is the APM PUBLISHED value, seeded and then never read: since
-- 2026-08-08 the rollup computes a CE's target as the mean of its active control
-- targets (rollup-spec §3). The column is kept as the recoverable anchor so the
-- published bar survives if that decision is revisited.
-- The same claim in migrations/0001_init.sql:58 is now false, and is deliberately
-- NOT edited — a migration should record what actually ran.
insert into public.competence_element (framework_id, area_id, code, name, target_level, sort_order)
select f.id, a.id, v.code, v.name, v.target, v.sort
from public.framework f
join public.competence_area a on a.framework_id = f.id
, (values
  ('4.3.1', 'Strategy', 'Perspective', 3, 0),
  ('4.3.2', 'Governance, structures and processes', 'Perspective', 3, 1),
  ('4.3.3', 'Compliance, standards and regulations', 'Perspective', 3, 2),
  ('4.3.4', 'Power and interest', 'Perspective', 3, 3),
  ('4.3.5', 'Culture and values', 'Perspective', 3, 4),
  ('4.4.1', 'Self-reflection and self-management', 'People', 3, 5),
  ('4.4.2', 'Personal integrity and reliability', 'People', 3, 6),
  ('4.4.3', 'Personal communication', 'People', 3, 7),
  ('4.4.4', 'Relationships and engagement', 'People', 3, 8),
  ('4.4.5', 'Leadership', 'People', 2, 9),
  ('4.4.6', 'Teamwork', 'People', 3, 10),
  ('4.4.7', 'Conflict and crisis', 'People', 3, 11),
  ('4.4.8', 'Resourcefulness', 'People', 3, 12),
  ('4.4.9', 'Negotiation', 'People', 3, 13),
  ('4.4.10', 'Results orientation', 'People', 3, 14),
  ('4.5.1', 'Project design', 'Practice', 2, 15),
  ('4.5.2', 'Requirements and objectives', 'Practice', 3, 16),
  ('4.5.3', 'Scope', 'Practice', 3, 17),
  ('4.5.4', 'Time', 'Practice', 3, 18),
  ('4.5.5', 'Organisation and information', 'Practice', 3, 19),
  ('4.5.6', 'Quality', 'Practice', 3, 20),
  ('4.5.7', 'Finance', 'Practice', 3, 21),
  ('4.5.8', 'Resources', 'Practice', 3, 22),
  ('4.5.9', 'Procurement', 'Practice', 2, 23),
  ('4.5.10', 'Plan and control', 'Practice', 3, 24),
  ('4.5.11', 'Risk and opportunity', 'Practice', 3, 25),
  ('4.5.12', 'Stakeholders', 'Practice', 3, 26),
  ('4.5.13', 'Change and transformation', 'Practice', 2, 27)
) as v(code, name, area_name, target, sort)
where f.name = 'IPMA ICB4' and f.version = 'v4.0.1' and a.name = v.area_name;

-- controls (ICB4 source text — never edited) -------------------------------
insert into public.control (framework_id, ce_id, code, indicator, description, active,
                            priority, reason, kib_note, apm_competence,
                            target_level, target_source, sort_order)
select f.id, ce.id, v.code, v.indicator, v.description, v.active,
       v.priority, v.reason, v.kib_note, v.apm_competence,
       v.target_level, v.target_source, v.sort
from public.framework f
join public.competence_element ce on ce.framework_id = f.id
, (values
  ('4.3.1.1', '4.3.1', 'Align with organisational mission and vision', 'The individual knows, reflects and can translate the organisation’s mission, vision and strategy into its project. The individual always needs to ensure that the project goals are in sync with the mission, quality policy and values of an organisation. If the relation between the project’s benefits and organisational purpose is vague, the individual still needs to perform periodic checking of the benefits against the purpose written in formal strategic documents. The align-ment is usually done by utilising diagnostic management control systems and formal tools (e.g. critical success factors, success criteria, key performance indicators, etc).', true, 'Medium', 'Partial fit. Setting or aligning project goals to strategy assumes authority a KIB PM does not hold - the sponsor sets project goals. The two monitoring measures (checking objectives and benefits stay in sync with strategy, and checking the project is delivering benefits) are within PM control during execution. Retained at Medium on the monitoring half.', null, 'No APM equivalent', 2, 'Derived (priority rule)', 0),
  ('4.3.1.2', '4.3.1', 'Identify and exploit opportunities to influence organisational strategy', 'The individual knows the strategy-making process, often done in a top-down fashion by the executive board/management board of an organisation. However, intended strategies are often not realised as the environment changes and, while pursuing a certain path, new opportunities and risks are emerging. Therefore, the individual needs to reflect not only the pre-set strategic goals, but also the tools and methods of questioning these goals and influencing the board to make the necessary improvements. These influences are managed through interactive control systems and by applying a bottom-up approach. Perspective 43', true, 'High', null, 'Senior baseline / junior target (provisional)', 'No APM equivalent', 3, 'Derived (priority rule)', 1),
  ('4.3.1.3', '4.3.1', 'Develop and ensure the ongoing validity of the business / organisational justification', 'The individual is able to provide a formal document which states the official reasons for a project, including the business or organisational benefits that the project has to deliver. This justification should also explain integration aspects with new elements in the project and should be the basis for the success criteria and benefits the project should deliver (the scope). The individual can create or facilitate, interpret, update and sometimes realise (parts of) the business justification which should not be a static document, but should be periodically updated throughout the realisation and re-assessed for validity. Furthermore, the individual should constantly monitor or control the configuration and check if the project has redundant or strategically obsolete elements and perform the proper alignment, even if this means terminating the project.', true, 'High', null, 'Senior baseline / junior target (provisional)', '5 Business case', 2, 'APM (published)', 2),
  ('4.3.1.4', '4.3.1', 'Determine, assess and review critical success factors', 'The individual is able to discern, define, interpret and prioritise critical success factors (CSFs) which directly relate to the project. CSFs are directly connected with the organisational objectives and business objectives of the project. Therefore by achieving the project’s benefits, the organisation fulfils strategic goals, tactical and operational objectives and ultimately organisational success. The individual can grasp both the formal and informal context of the factors and identify their influence on the final outcome of the project. The relative importance of the suc-cess factors may change, due to both contextual factors and the dynamics of the project itself. Personnel changes, both project-internal and project-external, may have influence, too. Therefore the individual should periodically be checking and assessing the actuality and relative importance of the CSFs and – when necessary – making changes in order to sustain success, even if this means the premature end of the project.', true, 'High', null, 'Senior baseline / junior target (provisional)', 'No APM equivalent', 3, 'Derived (priority rule)', 3),
  ('4.3.1.5', '4.3.1', 'Determine, assess and review key performance indicators', 'The individual is able to manage related key performance indicators (KPIs) for each CSF. KPIs are the core of many strategic performance management systems and are used for measuring or indicating the fulfilment of the CSF and achieving success. Usually KPIs are either pre-set by the organisation or developed by the individual using best practices or models (e.g. the balanced scorecard). KPIs can be used as leading measures (preceding a strategic event or milestone), lagging measures (following a strategic event or milestone) or real-time dashboards. Throughout the project, KPIs may change, due to both Perspective 45 contextual factors and the dynamics of the project itself. Personnel changes, both internal and external to the project, may also influence KPIs. Therefore the individual should periodically be checking and assessing the actuality and relative importance of the KPIs and – when necessary – make the required changes in order to sustain success. KPIs should also involve soft aspects, such as motivation, communication within the team, personal development of team members, etc, which reflect the strategic objective, i.e. the benefit one wants to achieve. Moreover, KPIs should cover a broad range of other aspects, varying from adhering to certain governance and support processes (for instance on decision-making, reporting, acquiring resources and administrative processes), meeting standards and regulations, to complying with cultural norms and values, both of the organisation and of the wider society.', true, 'High', null, null, 'No APM equivalent', 3, 'Derived (priority rule)', 4),
  ('4.3.2.1', '4.3.2', 'Know the principles of project management and the way in which they are implemented', 'The individual reflects the concepts of a project and management by projects and can explain the difference between different types of organisation settings (e.g. functional, matrix and project-oriented organisation), and knows how to optimally align performance with the current organisational setting. The indi-vidual can explain the characteristics and principles on which management by projects is based and is able to set up a project-oriented environment. Further-more, the individual is aware of the maturity concept of the project-oriented organisations covering organisational competences, project and programme competences, and individual competences.', true, 'High', null, null, '2 Governance arrangements', 3, 'APM (published)', 5),
  ('4.3.2.2', '4.3.2', 'Know the principles of programme management and the way in which they are implemented', 'If the project is part of a programme, the individual has to align the project with the programme and has to know how the principles of programme management are implemented in the specific organisation. The dependencies between the project and the programme as well as between the different projects within the programme have to be analysed in terms of input, goals, outcomes, etc. Dealing with those dependencies means setting up and maintaining interfaces between the project and the programme.', true, 'Medium', 'Knowledge-only measures. ICB4 conditions the KCI on the project being part of a programme, which is rare at KIB. Retained because the knowledge supports upward interfacing, but it is awareness-level, not a delivery capability.', null, 'No APM equivalent', 2, 'Derived (priority rule)', 6),
  ('4.3.2.3', '4.3.2', 'Know the principles of portfolio management and the way in which they are implemented', 'The individual knows the way in which portfolio management is implemented in the specific permanent organisation. Therefore the individual knows the portfolio criteria and required inputs and outputs and identifies the impact of the project Perspective 49 on the portfolio. The individual is able to discover different constraints within the portfolio and can take these constraints into account to harmonise resource utilisation of his or her project. The individual is able to filter and/or funnel the communication channels with the respective portfolio in order to positively influence the project performance. The individual knows the vertical (e.g. with the programme or portfolio manager) and horizontal (e.g. with other individuals in the same programme other project teams) lines of communication as part of the overall coordination process with a programme or portfolio.', true, 'Medium', 'Two of three measures are explanatory; the third (communicating within the portfolio to manage the project successfully) is an active behaviour that is real under KIB''s matrix structure with a portfolio manager in post.', 'Senior baseline / junior target (provisional)', 'No APM equivalent', 2, 'Derived (priority rule)', 7),
  ('4.3.2.4', '4.3.2', 'Align the project with supporting functions', 'Project supporting functions (a project office, a project management office or similar) provide multifaceted support to the project and/or the individual managing the project in relation to organisation, planning, reporting, meeting management, documentation, etc. To ensure the necessary support from the project supporting function, the individual has to know relevant contact people within the project supporting function and how to establish and maintain good relationships with them.', true, 'High', null, 'Assesses how well PMs use the PMO. Most diagnostic for the two ITD dotted-line PMs.', '2 Governance arrangements', 3, 'APM (published)', 8),
  ('4.3.2.5', '4.3.2', 'Align the project with the organisation’s decision-making and reporting structures and quality requirements', 'The success of a project is very much dependent on the right decisions made at the right level of the organisation at the right time. Every decision should be prepared, presented, accepted, recorded, communicated and finally imple-mented. Formal and informal routines and special rules for decision-making beyond the individual’s authority and responsibility exist in each organisation. Therefore, the individual requires knowledge of the decision-making structure and processes and the ability to structure and manage the project accordingly. Periodic reporting of the actual status is essential for trust by its stakehold-ers and to assure traceability of the progress. Different project stakeholders have different reporting needs (information requirements, method of delivery, reporting frequency) which the individual has to take into account. The parent organisation will have different forms of quality assurance which relate to projects (e.g. system assurance, project assurance, finance assurance, techni-cal assurance, security assurance, etc). For the individual it is important to take these into account in devising a quality assurance plan for his or her project, to decide which project areas could become quality assurance objects and to know which members of the project team should be involved in project assurance activities.', true, 'High', null, 'Senior baseline / junior target (provisional). Core escalation and governance control.', '2 Governance arrangements', 3, 'APM (published)', 9),
  ('4.3.2.6', '4.3.2', 'Align the project with human resource processes and functions', 'The human resource function provides multi-faceted support to the project in relation to team member contracts, temporary employment, training, salaries, incentives, stress, wellbeing, ethics and team entries and withdrawals. Perspective 51 A well-established relationship with the human resource processes and func-tions may increase the influence on resource availability and quality in terms of adequate authorities. To ensure the necessary support from the human resource function, the individual has to establish and maintain relationships with relevant contact people within it.', false, 'Low', 'HR owns contracts, temporary employment, salaries, incentives and training at KIB. A PM does not engage HR directly for resourcing - that runs through the PMO and the line. No measure describes work a KIB PM performs.', 'Reason type: belongs to another department (permanent)', 'No APM equivalent', null, 'n/a — inactive', 10),
  ('4.3.2.7', '4.3.2', 'Align the project with finance and control processes and functions', 'The finance and control function of an organisation is often established as a line function providing mandatory rules, procedures and guidelines. Knowing these rules and how to utilise them effectively and efficiently are crucial for the individ-ual for successful funding, monitoring and/or reporting on financial topics. The finance and control function of an organisation often serves as a support func-tion, offering a variety of utility functions for the individual such as how to apply for, justify, manage and report on financial resources and how to administer, distribute, monitor and manage finances. The individual needs to know various financial models for funding (e.g. public, private, public-private partnerships, subsidies, commercial, etc) endorsed by the permanent organisation. To ensure the necessary support from the finance and control function, the individual can benefit from establishing and maintaining relationships with the relevant contact people within the finance and control function.', true, 'Medium', 'Knowing Finance''s processes, distinguishing compulsory from optional and reporting financial status are PM work. Knowing funding models (public, private, PPP, subsidies) is not a KIB PM''s decision.', 'Senior baseline / junior target (provisional). Islamic-banking language review needed at Phase 2.', '4 Financial management', 3, 'APM (published)', 11),
  ('4.3.3.1', '4.3.3', 'Identify and ensure that the project complies with all relevant legislation', 'The individual knows the legal policies of an organisation and is able to implement them in a project. Furthermore the individual knows which parts of law regulations (e.g. civil, criminal, labour, intellectual property, etc) and common good practices are relevant to the project. The individual has to ensure that the project oper-ates within the law and should be able to recognise or find out which activities have special legal requirements and what law principles apply to it. The individual is able to recognise the unknown legal issues that need to be considered and therefore knows the formal procedures for obtaining specialist advice and how to identify and provide the relevant project information. The individual also knows which requirements of the regulatory agencies concerned with the project scope are relevant to the project, how these requirements can be satisfied and which inspection procedures should be applied.', true, 'High', null, 'Senior baseline / junior target (provisional)', '18 Ethics, compliance and professionalism', 3, 'APM (published)', 12),
  ('4.3.3.2', '4.3.3', 'Identify and ensure that the project complies with all relevant health, safety, security and environmental regulations (HSSE) © 2015 International Project Management Association', 'The individual knows which of the health, safety, security and environmental (HSSE) regulations are relevant to the project. Further, the individual is able to recognise any potential HSSE issue that needs special attention. The individual is able to determine how project activities or project products can affect the project team members and those who will use the product and the environment and then applies HSSE protective measures when necessary. The individual balances eco-nomic, social and environmental aspects of the project to meet the requirements for sustainable development and to make the project results sustainable. Perspective 55', true, 'Medium', 'Health, safety and environmental content applies at KIB in different form from physical delivery - digital ergonomics and DSE, psychosocial safety during transformation, e-waste from system migrations, and CBK cyber and operational resilience requirements. No measure is out of scope once correctly interpreted.', 'Guidance block written. Sharia compliance deliberately excluded here - sits with 4.3.3.1 and 4.3.3.3.', '18 Ethics, compliance and professionalism', 3, 'APM (published)', 13),
  ('4.3.3.3', '4.3.3', 'Identify and ensure that the project complies with all relevant codes of conduct and professional regulation', 'The individual should be able to identify relevant professional regulations for the context in which the project operates. Each context usually has specific codes of conduct (ethical norms written down in formal documents) and trading customs which sometimes are prescribed by law. Moreover they are often directly tied with procurement procedures and, if not understood, could be a high risk for a project.', true, 'High', null, 'No seniority flag - ethical conduct is absolute from day one.', '18 Ethics, compliance and professionalism', 3, 'APM (published)', 14),
  ('4.3.3.4', '4.3.3', 'Identify and ensure that the project complies with relevant sustainability principles and objectives', 'The individual is able to assess the impact of the project on the environment and society. Realising his or her responsibility, the individual researches, recom-mends and applies measures to limit or compensate negative consequences. The individual follows (or even exceeds) guidelines and rules on sustainable develop-ment coming from within the organisation and from the wider society and is able to realise a workable balance between the demands of society, impacts to the eco-environment and the economy. The individual understands that sustainabil-ity aspects, measures and attitudes often vary in different countries and cultures.', true, 'Low', 'Reinstated. Originally excluded as not applicable at KIB today. Environmental obligations under Kuwait Environmental Protection Law No. 42 of 2014 (as amended by Law No. 99 of 2015) apply to project e-waste from system migrations, and Boursa Kuwait ESG guidance bears on vendor selection. Retained at Low pending confirmation of KIB''s ESG position.', 'Reason type: not applicable at KIB today - EXPIRED and reversed in-session.', '3 Sustainability', 3, 'APM (published)', 15),
  ('4.3.3.5', '4.3.3', 'Assess, use and develop professional standards and tools for the project', 'The individual is able to comply with and utilise top professional standards. Those good practices in project management come from a combination of the world leading standards and personally developed tools and methods. The individual takes them into account while selecting appropriate tools, methods and con-cepts (e.g. project lifecycle, stakeholder management, risk management, etc). Therefore an individual always tries to find the best recipe for managing the project by utilising top professional standards (one or several) and adding and developing further improvements.', true, 'Medium', 'Identifying and applying relevant professional standards is PM work. Developing custom-made standards and managing the risk of applying a standard are closer to PMO methodology ownership, which is the Head of PMO''s role.', 'Senior baseline / junior target (provisional)', '18 Ethics, compliance and professionalism', 3, 'APM (published)', 16),
  ('4.3.3.6', '4.3.3', 'Assess, benchmark and improve the organisational project management competence', 'The benchmarking project management competence is a process of continuous improvement by comparing the organisation’s project management processes with those which are identified as good practice. The individual strives to develop project management competence. The good practices can often be identified as Perspective 57 those that apply in world-class organisations. Usually these organisations are promoted as top project management performers and have won internationally recognised project management awards (e.g. IPMA Global Project Excellence Award). The purpose of the benchmarking process is to gain superiority in project management by acquiring the know-how of a superior organisation. Organisational benchmarks often follow a staged maturity or competence model of organisations defining what structures, processes, methods and indi-vidual skills an organisation has to fulfil in order to reach a certain maturity level or class of competence. Benchmarking can be conducted on an internal basis (against different projects within an organisation), a competitive basis (against an organisation which is a direct competitor – often hard to tackle) and a functional or generic basis (against an organisation not competing in the same market or within the same industry). The Individual always tries to improve their project management in a way that contributes to the organisation’s strategic goals. Furthermore, the individual is able to identify the governing processes and structures (e.g. a project management office) relevant to the project man-agement process and is able and willing to do or suggest improvements on an organisational level. Finally, improvements made are disseminated throughout the organisation.', true, 'Medium', 'PMs contribute to improving organisational PM competence from delivery experience - identifying deficient areas and disseminating know-how. Ownership of benchmarking and organisational maturity assessment remains with the Head of PMO, so retained at Medium rather than High.', 'Senior baseline / junior target (provisional)', '10 Capability development', 2, 'APM (published)', 17),
  ('4.3.4.1', '4.3.4', 'Assess the personal ambitions and interests of others and the potential impact of these on the project', 'People have goals and ambitions, for example career goals, or a desire to improve society or improve themselves. They also have interests that are related to these ambitions and influence the interests they have in the project and its success. Part of their ambitions and interests will often be congruent with their present formal position, that is, performing the tasks that they are formally required to do may help realise their ambitions and interests. Then again, their ambitions and interests may go beyond (or even be partly at odds with) the formal interests of their formal position. Being able to identify the ambitions and personal interests of people (stakeholders, team members or colleagues) is often necessary in order to work with them in an efficient and effective way.', true, 'High', null, null, '13 Stakeholder engagement and communication management', 3, 'APM (published)', 18),
  ('4.3.4.2', '4.3.4', 'Assess the informal influence of individuals and groups and its potential impact on the project', 'Informal influence has to be distinguished from the formal influences as laid down in organisational documents and processes. People may have influence for many reasons and through many different means. Apart from the formally agreed on legitimate power (e.g. of department heads, executives, judges and school teach-ers) there are many other bases of power, for instance coercive, reward, referent and expert power. Relationships are a strong base of power, too. Influencing deci-sions through use of personal relationships is a common and often effective way. There is often a marked difference in the ability of people or groups to influence certain kinds of decisions, or decisions taken in a specific knowledge area or part of the organisation (‘reach’ of influence). Every person and group influence has its own reach and it is important to know this reach. Perspective 61', true, 'High', null, null, '13 Stakeholder engagement and communication management', 3, 'APM (published)', 19),
  ('4.3.4.3', '4.3.4', 'Assess the personalities and working styles of others and employ them to the benefit of the project', 'Everybody is unique and will act and operate in his or her specific way. Style is also influenced by cultural factors, as discussed in ‘Culture and values’. Different people may have the same ambitions and/or interests, yet may use a different style in using their influence. Other people may display the same behaviour or style, yet differ in ambitions and/or interests. The individual has to acknowledge the differences while working with individuals and groups in an efficient and effective way.', true, 'High', null, null, '13 Stakeholder engagement and communication management', 3, 'APM (published)', 20),
  ('4.3.5.1', '4.3.5', 'Assess the culture and values of the society and their implications for the project', 'All projects are embedded in a society (sometimes even in more than one). The society’s values and unwritten rules can deeply influence the way in which communication is executed and decisions are made. It can also influence how transgressions from the common norm are judged and dealt with; it can define or influence working hours and how, when, where and with whom information, office space and meals can be shared, etc. The individual needs a working knowledge of the cultural basis, values and norms of the society or societies in which the project takes place. The individual should be able to discern the relevant implications of these cultural aspects for the project, take these into account in the approach and periodically review them.', true, 'High', null, null, '17 Diversity and inclusion', 3, 'APM (published)', 21),
  ('4.3.5.2', '4.3.5', 'Align the project with the formal culture and corporate values of the organisation', 'All projects need to be aligned with the values of the organisation and have to follow the formal cultural rules and demands of related functional departments or support units and the culture of superordinate projects and strategic deci-sion-making bodies. Sometimes the espoused values are written down in one or more documents (for instance mission statement, quality policy, or corporate values). The individual should be able to discern the relevant implications of these cultural aspects for the project and take these into account in the approach. Moreover, the individual needs to be sure that the project supports the sus-tainable development of the organisation, which also includes corporate social responsibility (CSR). Perspective 65 CSR is a lever of control in complying with legal and non-governmental regulations, professional standards and other ethical and international norms. Through CSR an organisation encourages a positive impact on its activities on the environment, consumers, employees, communities, stakeholders and all other members of the society.', true, 'High', null, 'Phase 2: one measure covers CSR - relates to 4.3.3.4.', '18 Ethics, compliance and professionalism', 3, 'APM (published)', 22),
  ('4.3.5.3', '4.3.5', 'Assess the informal culture and values of the organisation and their implications for the project', 'All projects are linked to an organisation (or more than one) with its own infor-mal culture. While the formal aspects of the organisational culture can have a significant influence, many more aspects also influence an organisation’s culture or subcultures. These include its architecture, furniture, dress codes, office jokes, etc. Assumptions are deeply embedded, usually unconscious behaviours, such as the way people address and treat each other (including subordinates and manag-ers), how problems and challenges are dealt with and the tolerance for mistakes or irregular behaviour, all resulting from the history and cultural background of the organisation, its employees and its management. The individual should analyse the cultural basis of the organisation(s) for and in which the project takes place. The individual should be able to discern the relevant implications of these cultural aspects for the project and take these into account in his or her approach.', true, 'High', null, null, '17 Diversity and inclusion', 3, 'APM (published)', 23),
  ('4.4.1.1', '4.4.1', 'Identify and reflect on the ways in which own values and experiences affect the work', 'To identify and reflect personal values and passions the individual has to acknowledge and reflect on his/her intrinsic set of opinions, standpoints, ideals and ethical values. This is the basis for consistent decisions and actions. Personal experience has a strong influence on how the individual makes sense of situations and people. His or her personal experience of how the world works and how people behave influences the way the individual thinks and acts. By understanding the personal sense-making processes, the individual can iden-tify why his or her interpretation might differ from someone else’s and so reduce the effect of bias. The opposite is to neglect the influence of experience and expect that everyone sees the ‘reality’ in the same way as the individual.', true, 'High', null, null, 'No APM equivalent', 3, 'Derived (priority rule)', 24),
  ('4.4.1.2', '4.4.1', 'Build self-confidence on the basis of personal strengths and weaknesses', 'Being self-aware includes reflection on personal strengths and weaknesses. The individual is aware of what he or she is good at and passionate about and which tasks should be delegated or left to others. Knowing his or her personal talents and accepting limitations creates a feeling of personal worth. The individual demonstrates self-confidence by relying on personal capacities and capabilities. The opposite is to remain troubled about yourself or your personality, continuing to doubt your talents and potential and overreacting if others impose on your personal weaknesses.', true, 'High', null, 'Phase 2: ''maintains eye contact'' measure is culturally loaded - address in guidance.', 'No APM equivalent', 3, 'Derived (priority rule)', 25),
  ('4.4.1.3', '4.4.1', 'Identify and reflect on personal motivations to set personal goals and keep focus', 'Knowing one’s personal motivations enables the individual to set personal goals that give direction and release energy. The individual knows what drives him or her and can transform this into personal goals. The individual has control over his or her emotions, even when provoked. The opposite is to ‘go with the flow’, live life as it comes and refrain from giving a direction. Once the goals are set, the individ-ual has a diligent approach to staying focused on the tasks. The individual is able to focus on tasks despite interruptions and is aware of the instances that lead to distraction. The individual avoids procrastination and postponement, which causes stress to the individual as well as to teams. This also includes the applica-tion of prioritisation techniques. Keeping focus includes the ability to cope with daily work as well as communications and relationships.', true, 'High', null, null, 'No APM equivalent', 3, 'Derived (priority rule)', 26),
  ('4.4.1.4', '4.4.1', 'Organise personal work depending on the situation and own resources', 'No two situations are the same. What works or worked in one situation may not work in another. The individual therefore strives to ‘read’ situations and people and adapts behaviour to the specific circumstances in order to realise the intended results and reach his or her goals. By choosing a personal organisation and man-aging his or her own resources, the individual shows the ability to prioritise and balance the various tasks in an effective and efficient way. Time-, money- and energy-wasting is avoided by prioritising responsibilities and performing value-adding tasks. The individual arranges his or her workload to avoid too much stress and includes relaxation when possible and necessary.', true, 'High', null, null, 'No APM equivalent', 3, 'Derived (priority rule)', 27),
  ('4.4.1.5', '4.4.1', 'Take responsibility for personal learning and development', 'The individual is focused on continuous learning and always strives to improve the quality of his or her work, actions and decisions. Accepting feedback and seeking consultation enables personal development and learning. If the individual understands and utilises the perceptions and views of others, including critical observations or remarks, personal positions and behaviour can be questioned and improved. The opposite is to remain unchanging, seeing all feedback as criticism, never accepting criticism and refusing to alter his or her ways. The individual strives to develop by leveraging all criticism and feedback as opportunities for growth.', true, 'High', null, null, 'No APM equivalent', 3, 'Derived (priority rule)', 28),
  ('4.4.2.1', '4.4.2', 'Acknowledge and apply ethical values to all decisions and actions', 'The individual should acknowledge his or her own values, as these values are the foundation for consistent decisions and actions. Understanding values includes being able to express opinions and positions on a variety of topics. The individ-ual communicates his or her principles, thereby demonstrating what they stand for. The individual makes others feel secure by being predictable in decisions and actions. The individual is able to identify inconsistencies and to articulate reasons for discord between statements and actions.', true, 'Low', 'Held at Low. Its first three measures are near-identical to 4.4.1.1 (knows and reflects own values; uses own values to shape decisions; communicates own principles). Duplication neutralised by priority rather than by exclusion.', 'Duplication case - Phase 2 review with 4.4.1.1.', '18 Ethics, compliance and professionalism', 3, 'APM (published)', 29),
  ('4.4.2.2', '4.4.2', 'Promote the sustainability of outputs and outcomes', 'Promoting sustainability means focusing on the endurance of solutions even when engaged in time-limited tasks. Sustainability is not only about social equity, environment protection or economic results. It is the consideration of the long-term outcomes and effects of behaviour. The individual has the ability to keep the bigger picture in mind and act accordingly.', true, 'High', null, 'Not ESG sustainability - about endurance of solutions. Description carries it; no guidance block needed.', '18 Ethics, compliance and professionalism', 3, 'APM (published)', 30),
  ('4.4.2.3', '4.4.2', 'Take responsibility for own decisions and actions', 'To take responsibility means the individual takes decisions and acts while keeping in mind that the individual is fully liable for the consequences – in both a positive and negative way. The individual sticks by decisions and agreements established with others. The individual feels responsible for the team success on behalf of all the interested parties. People 75', true, 'High', null, null, '18 Ethics, compliance and professionalism', 3, 'APM (published)', 31),
  ('4.4.2.4', '4.4.2', 'Act, take decisions and communicate in a consistent way', 'Consistency means that the individual makes sure that words, behaviour and actions match. By applying the same guiding principles throughout your actions, decisions and communication your behaviour is predictable and repeatable in a positive sense. Being consistent does not exclude flexibility in revising plans if the need for changes is indicated or to adapt to special situations.', true, 'High', null, null, '18 Ethics, compliance and professionalism', 3, 'APM (published)', 32),
  ('4.4.2.5', '4.4.2', 'Complete tasks thoroughly in order to build confidence with others', 'The individual completes tasks in a thorough and careful way. This inspires others to be confident and make promises and agreements. The individual is recognised as someone on whom others rely. Work results would be characterised by others as consistently good quality.', true, 'High', null, null, '18 Ethics, compliance and professionalism', 3, 'APM (published)', 33),
  ('4.4.3.1', '4.4.3', 'Provide clear and structured information to others and verify their understanding', 'To give clear information means to structure and translate information in such a way that the receiver can understand and use it. The individual must utilise a logical and structured way of communicating in order to verify understanding. The individual must obtain confirmation that the receiver of information has understood the message as intended. That means focusing on the receiver, not on the information itself, and asking for validation when needed.', true, 'High', null, null, '13 Stakeholder engagement and communication management', 3, 'APM (published)', 34),
  ('4.4.3.2', '4.4.3', 'Facilitate and promote open communication', 'To facilitate and promote open communication means actively inviting others to give their input and opinions on relevant topics. This requires an atmosphere of confidence, so that people can express their ideas and opinions without being rebuffed, punished or ridiculed. It should be made clear when and how others are free and/or invited to propose ideas, emotions and/or opinions, and when the time is less appropriate. In the latter situations, people and their input should still be treated with respect. To listen and give feedback is to seize opportunities for the exploration and exchange of opinions. The individual has a genuine interest in others’ views and creates open and informal frameworks for feedback. The individual makes people feel that they and their opinions are valued.', true, 'High', null, null, '13 Stakeholder engagement and communication management', 3, 'APM (published)', 35),
  ('4.4.3.3', '4.4.3', 'Choose communication styles and channels to meet the needs of the audience, situation and management level', 'The individual chooses the appropriate way of communicating for the target audience. The individual is able to communicate on different levels and through different channels. Formal or informal, neutral or emotional communication should all be considered, as well as whether written, oral or visual communica-tion is most appropriate.', true, 'High', null, null, '13 Stakeholder engagement and communication management', 3, 'APM (published)', 36),
  ('4.4.3.4', '4.4.3', 'Communicate effectively with virtual teams', 'A virtual team consists of individuals who work across time zones, space and/or organisational boundaries. Communication within virtual teams is a challenge, as not all are located in the same environment and/or organisation and they may be distributed over several organisations, cities, countries or continents. Communication between virtual team members is often asynchronous and not face-to-face, and has to use modern communication technology. The commu-nication procedures have to consider aspects such as language, channel, content and time zones.', true, 'High', null, 'Virtual-team framing applies at KIB via ITD dotted-line PMs and offshore vendor teams, not geography.', '13 Stakeholder engagement and communication management', 3, 'APM (published)', 37),
  ('4.4.3.5', '4.4.3', 'Employ humour and sense of perspective when appropriate', 'Work in projects can often be stressful. Being capable of viewing situations, problems and even your own work from different viewpoints is an important asset. Humour enables individuals to acquire a sense of perspective – a way of judging how good, bad or important something is compared with other things. The release of tension through humour often facilitates cooperation and decision-mak-ing. Humour is a powerful tool to decrease tension in situations where conflicts threaten to arise. Provided it is used in the right way, at the right time and with respect, humour can also facilitate communication.', true, 'Medium', 'Retained as a real capability - perspective-taking and tension management support delivery under pressure. Held at Medium because the measures are largely unobservable and humour norms differ across a multinational team.', null, '13 Stakeholder engagement and communication management', 3, 'APM (published)', 38),
  ('4.4.4.1', '4.4.4', 'Initiate and develop personal and professional relationships', 'To initiate and develop personal relationships is to seek and make use of chances to establish contact with other people. The individual demonstrates interest in people and is ready to engage with them. The individual utilises possibilities and situations to create and maintain personal and professional contacts. The indi-vidual is present, available, open for dialogue and actively staying in contact. The individual is visible and accessible for team members, clients, customers or other stakeholders. The individual acts attentively, acknowledges others and keeps them informed.', true, 'High', null, null, '13 Stakeholder engagement and communication management', 3, 'APM (published)', 39),
  ('4.4.4.2', '4.4.4', 'Build, facilitate and contribute to social networks', 'Building, facilitating and contributing to social networks has various levels. On the lowest level, the individual joins and contributes to networks with inter-esting and/or useful others. By doing so, new relationships are established. On the second level, the individual creates new networks and circles of his or her own and so opens up new communication flows between others. The indi-vidual thus acts as a facilitator or communication hub. The next level of social networking is to make one’s own relationships available for others. This means enabling, enforcing and establishing relationships between others that are sus-tained even without the individual being engaged.', true, 'Medium', 'Joining and contributing to networks is relevant. The upper rungs - creating one''s own networks, organising networking events - describe a role a PM does not occupy at KIB.', 'Revisit: informal networks may be under-weighted here. Review with 4.5.12.5.', '13 Stakeholder engagement and communication management', 3, 'APM (published)', 40),
  ('4.4.4.3', '4.4.4', 'Demonstrate empathy through listening, understanding and support', 'To demonstrate empathy means to show real interest and involvement with others and their wellbeing. The individual listens attentively to others and ensures understanding by asking questions for clarification or detail. The indi-vidual recognises emotions expressed or possibly just experienced by others. The individual relates and reacts to these emotions in a sympathetic or com-passionate way. The individual offers support, even when it is not asked for.', true, 'High', null, null, '13 Stakeholder engagement and communication management', 3, 'APM (published)', 41),
  ('4.4.4.4', '4.4.4', 'Show confidence and respect by encouraging others to share their opinions or concerns', 'Having confidence in someone means having belief in their future actions or decisions and being convinced of their positive intentions. The individual does not have a hidden agenda but shares information with others. The individual also accepts that showing confidence is an investment with an insecure out-come. The individual takes others, their talents and opinions seriously, and that success also depends on their actions and commitment. To get optimal team performance it is crucial to understand the motivation of the team members. To get there, the individual has to spend time with people in order to under-stand who they are and what makes them tick. The individual should keep in mind that the values, experiences and goals of others might be very different from his or her own. Acting respectfully means treating others in a respectful way, as you would like to be treated yourself. The individual takes others seri-ously by cherishing their opinions, their work and their personality, regardless of gender, race, social status or background. Cultural diversity is respected. The individual considers codes of conduct as guidelines for decisions and behaviour.', true, 'High', null, 'Contains the diversity and inclusion content the brief flagged as an ICB4 gap - may close the need for APM C17.', '17 Diversity and inclusion', 3, 'APM (published)', 42),
  ('4.4.4.5', '4.4.4', 'Share own vision and goals in order to gain the engagement and commitment of others © 2015 International Project Management Association', 'To share a vision and goals implies acknowledging and demonstrating a positive and enthusiastic attitude towards a certain task, process or goal while showing a realistic optimism. To inspire others requires an ambitious yet clear vision, realistic objectives and the ability to achieve commitment from the people concerned. To be self-committed is an important requirement for that. Inspiration is often achieved through a shared vision – a view of the future that people can believe in and want to be part of. This vision can either be explicit (even written down) or implicit. The vision serves as a motivator for change. To engage people and get their commitment means making them feel per-sonally responsible for a good outcome. This can be done by various means – by asking their advice, by making them responsible for a task or by involving them in decisions. The individual should make optimal use of the skills and experience of his or her co-workers. This means that people should be involved in decisions on the basis of what they can add to the existing knowledge. The same goes for sharing information, as this can enhance commitment. However, the individual must also be aware of the dangers of information overload. As every team member has their own tasks, in some cases it is better to share information on a ‘need to know’ basis.', true, 'High', null, null, '13 Stakeholder engagement and communication management', 3, 'APM (published)', 43),
  ('4.4.5.1', '4.4.5', 'Initiate actions and proactively offer help and advice', 'To take the initiative means having the tendency and ability to start an unre-quested action, including coming up with a proposal or advice, taking the lead and/or giving or helping without first being invited to do so. Taking the initia-tive requires the ability to think ahead, both of possible situations and possible solutions. Taking the initiative adds to one’s influence and heightens one’s visibility. On the other hand, if the initiative is not welcomed or turns out badly, there is a risk of losing influence or status. So every initiative should always be guided by a careful weighing of pros and cons.', true, 'High', null, null, '15 Leadership', 2, 'APM (published)', 44),
  ('4.4.5.2', '4.4.5', 'Take ownership and show commitment', 'To take ownership means demonstrating personal buy-in. This commitment to the objectives of the project makes people believe in its value. The individual acts as an entrepreneur by taking full responsibility for the process and by spotting opportunities for improvement. The individual constantly monitors processes and results to spot the right occasions for intervention and improvement and opens up possibilities for learning. People 87', true, 'High', null, 'Soft duplication with 4.3.1.5 (KPIs) - logged, not actioned.', '15 Leadership', 2, 'APM (published)', 45),
  ('4.4.5.3', '4.4.5', 'Provide direction, coaching and mentoring to guide and improve the work of individuals and teams', 'To give direction, coaching and mentoring means to give guidance and support to people and teams and establish conditions that engage people with their assignments. Coaching and mentoring is focused on improving the abilities and self-reliance of team members. Direction is guiding them in their activities. The individual creates and communicates personal and common objectives and acts from these. The individual creates and shares a vision that leads the project. To give direction, coaching and mentoring requires the ability to keep a cool head in demanding and unclear situations. It also requires that the individual knows when and in what direction coaching or mentoring are needed and what form they should take. Sometimes it may be better to withhold a proposal or decision for a while to promote the self-reliance or creativity of teams or individuals.', true, 'High', null, null, '15 Leadership', 2, 'APM (published)', 46),
  ('4.4.5.4', '4.4.5', 'Exert appropriate power and influence over others to achieve the goals', 'To exert power and influence means being visible as a leader and opening up the possibility for others to follow. Therefore one needs to understand the demands of colleagues, subordinates, clients and other interested parties, to respond to them and influence their expectations and opinions. To exert influence also means directing other people’s actions, whether or not one is in command. A leader actively shapes views and creates the perception of situations, results and rela-tionships through words and actions. Sometimes the use of power is necessary to realise results or resolve deadlock; in other situations, a simple, wellplaced word may be even more effective. The open use of power may create resentment or invite counterpower, so a leader should know when to use what means of power and in what way. The use and effectiveness of power and influence is always tightly linked to communication. A leader should know the possibilities and limits of each communication means and channel.', true, 'High', null, 'Applied counterpart to 4.3.4.2. ''Perceived as the leader'' is externally verifiable.', '15 Leadership', 2, 'APM (published)', 47),
  ('4.4.5.5', '4.4.5', 'Make, enforce and review decisions', 'Making decisions means being able to select a course of action based on several possible alternative paths. Often decisions are made with incomplete or even contradictory information and with uncertain consequences. Making decisions entails consciously selecting from alternatives and choosing the one that is most consistent and aligned with the objectives. Decisions should be taken based upon analysis of the facts and incorporating the views and opinions of others. Sometimes the information quality is so poor that decisions are based on intuition. Reviewing and being prepared to change prior decisions based on new information is an essential part of the ability to take decisions. Decisions often have to be taken by others (for instance by line managers, steering committees, etc). The leader exerts his or her influence to have these others take the right decisions at the right time. People 89', true, 'High', null, null, '15 Leadership', 2, 'APM (published)', 48),
  ('4.4.6.1', '4.4.6', 'Select and build the team', 'To ensure successful teamwork, the right resources for the team have to be selected. Apart from ensuring that they have the necessary knowledge and skills, the individual leading the team also has to take care that the selected team members have the right ‘chemistry’ to be able to work together as a team. Before the chosen team can start performing, the individuals have to generate an under-standing of themselves as a team. The role of the individual leading the team is to translate individual motivation into team performance. The members have to be enabled to learn about each other and the tasks they are facing. Team build-ing is a continuous task, but as the team matures the necessary activities for the individual leading the team change accordingly.', true, 'High', null, 'Phase 2: team-selection measure assumes authority a KIB PM lacks - address in guidance. Building half carries the priority.', '16 Team management', 3, 'APM (published)', 49),
  ('4.4.6.2', '4.4.6', 'Promote cooperation and networking between team members', 'Stimulating cooperation means actively influencing team participants to work together and contribute with their experience, knowledge, opinions, ideas and concerns, for the sake of the agreed objectives. Discussions and disagreements are an unavoidable consequence of this, but as long as the individual leading the team makes sure that a productive and respectful atmosphere is main-tained, team members can expect that conflict will lead to better performance. Whenever individual team members set out to disrupt cooperation by playing a divisive or counter-productive role, the individual leading the team needs to address this by correcting and, in extreme cases, replacing the team member. The team leader can stimulate networking through physical and virtual activities where team members share their knowledge and motivate and inspire each other.', true, 'High', null, null, '16 Team management', 3, 'APM (published)', 50),
  ('4.4.6.3', '4.4.6', 'Support, facilitate and review the development of the team and its members', 'Team development involves continuously developing the team, encouraging members to gain new knowledge and skills. The role of the individual leading the team is to support, enable and review these learning efforts as well as creating opportunities to share knowledge between team members, other teams and the organisation outside the project. People 93', true, 'Medium', 'Promoting learning, knowledge sharing and lessons-learned sessions is PM work. Providing seminars, workshops and self-development time assumes budget and scheduling authority over team members that sits with the line and HR.', 'Lessons-learned cluster: 4.4.6.3, 4.4.7.4, 4.5.1.2, 4.5.10.6.', '16 Team management', 3, 'APM (published)', 51),
  ('4.4.6.4', '4.4.6', 'Empower teams by delegating tasks and responsibilities', 'Responsibility creates involvement. The individual leading the team increases involvement – and individual and collective empowerment – by delegating tasks and problems to teams or team members. Dependent on their team maturity, delegated tasks can be big, challenging and important. The output of delegated tasks to individuals and teams should be measured, with feedback cycles for the team to ensure learning occurs.', true, 'High', null, null, '16 Team management', 3, 'APM (published)', 52),
  ('4.4.6.5', '4.4.6', 'Recognise errors to facilitate learning from mistakes', 'The individual leading the team makes sure that the effect of errors and mistakes on the outcomes, processes and success of the project are kept to a minimum. The individual is aware that mistakes can always happen and understands and accepts that people make errors. The individual analyses mistakes and facilitates learning from mistakes. Errors and mistakes are used as a platform for change and improvement so that there is less chance of future errors. In some cases, the individual leading the team can even promote behaviour that increases the chance of errors, if the project needs innovative ways to overcome problems and difficulties. Even then, the individual leading the team ensures that the final outcomes, processes and project success are not affected negatively. The individual seeks root causes for mistakes and takes effective action to ensure that the same mistakes do not occur again.', true, 'High', null, 'Psychological-safety control - low score signals a team that hides problems.', '16 Team management', 3, 'APM (published)', 53),
  ('4.4.7.1', '4.4.7', 'Anticipate and possibly prevent conflicts and crises', 'To be aware of potential conflicts and crises means being alert and observant of situations that might lead to disagreements. Possible conflicts are ideally iden-tified and prevented or tackled at an early stage before they expand. Prevention includes pre-empting conflict topics, keeping team members with conflicting characters or interests in separate teams and/or delegating conflict-sensitive items to specific people. Stress is a very likely factor in potential conflicts or crises, as people tend to get irritable under pressure. The individual should therefore be able to recognise, assess and reduce individual stress levels.', true, 'High', null, null, '14 Conflict resolution', 3, 'APM (published)', 54),
  ('4.4.7.2', '4.4.7', 'Analyse the causes and consequences of conflicts and crises and select appropriate response(s)', 'Conflicts pass through various stages. These stages can be summarised in three broad categories: • Latent (potential, slumbering, but not yet visible or acknowledged). This exists whenever individuals or groups have differences that bother one or the other, but the differences are not great enough to cause one side to act to alter the situation. • Emergent (visible but still rational). This may happen when a ‘triggering event’ happens, for instance an open disagreement on a topic. This topic is either the real cause of the conflict, or a pretext for another conflict of interest or character. When the conflict is emergent, the involved parties are still on speaking terms and can discuss rational solutions. • Escalated (open conflict). In this phase the parties are openly and emotionally at odds with each other and are not able or willing any more to discuss solutions calmly and rationally. Other people are tending to take sides, or they are or urged to do so. In some situations legal steps may be taken or considered. Crises, by contrast, jump immediately to the third level without acknowledged intermediary steps. However, they are often not the result of conflict situations but may arise because of a sudden or suddenly discovered issue – a major risk occurring, an outside event with great impact, etc. The art of conflict and crisis management is to assess causes and consequences and obtain additional infor-mation for use in the decision-making process to define possible solutions. Conflicts and crises can have very different causes, varying from factual dis-agreements to character conflicts, and they may have origins that are external to the project or even the organisation. Depending on the causes, different solutions may be possible. Crises can also be differentiated by their potential impacts. Depending on the specific stage, different approaches to soothe, solve or escalate the conflict or crisis can be chosen.', true, 'High', null, null, '14 Conflict resolution', 3, 'APM (published)', 55),
  ('4.4.7.3', '4.4.7', 'Mediate and resolve conflicts and crises and/or their impact', 'Often conflict or crisis management has to be performed against a background of individuals and/or groups who are angry or in panic mode. In a minimum amount of time, the individual has to pull the information together, weigh the options, aim for a positive and preferably synergistic solution and, most importantly, stay calm and in control. In these circumstances, relaxation and balanced judgment are important qualities. In situations of crisis the ability to act decisively is most important. The potential means of resolving conflicts involve collaboration, compro-mise, prevention or use of power. Each depends on achieving a balance between one’s own and others’ interests. Cooperative conflict management requires a willingness to compromise among all parties. In the early stages of conflicts the individual can act as a moderator/mediator – at least when the individual is not directly involved. The individual brings the conflicting parties together and enables communication without being too judg-mental. In later stages the options may include use of power, escalation to higher management, professional mediation and/or legal measures.', true, 'High', null, 'Phase 2: ''disciplinary or legal measures'' measure is out of PM authority - address in guidance.', '14 Conflict resolution', 3, 'APM (published)', 56),
  ('4.4.7.4', '4.4.7', 'Identify and share learning from conflicts and crises in order to improve future practice', 'Once a conflict has been resolved, it is important to restore a sense of harmony and equilibrium to the environment. Stimulating learning from conflicts and crises People 99 means the individual can question the origins and causes of a conflict on a meta-level. Furthermore the individual can differentiate between environmental coinci-dences and true causes of a conflict or crisis, learn from them and encourage the team to do the same, so that they cope better with similar situations in the future.', true, 'High', null, 'Lessons-learned cluster.', '14 Conflict resolution', 3, 'APM (published)', 57),
  ('4.4.8.1', '4.4.8', 'Stimulate and support an open and creative environment', 'The individual creates a work environment that encourages people to share their knowledge and contribute their ideas and opinions. To stimulate and support creativity and innovation, the individual needs to be open to original and imaginative ways to overcome obstacles. These ways may include new products, processes or procedures or could involve revising specific tasks or roles and responsibilities. The individual can make others feel they are wel-come to express themselves, so that the project can benefit from their input, suggestions, ideas and concerns. This is necessary as a means of benefiting from others’ knowledge and experience. Openness is important as in every project professionals with various backgrounds and abilities have to work together. Most of the team members have an area of expertise where they are more knowledgeable than the individual. The relationships in the team are built on mutual respect, trust and reliability. So the individual should regularly ask people for their input and show willingness to understand and possibly adopt their ideas. Of course there is a time and place for everything, so the individual should also make clear when there is time for creative input and when not.', true, 'High', null, 'Senior baseline / junior target', 'No APM equivalent', 3, 'Derived (priority rule)', 58),
  ('4.4.8.2', '4.4.8', 'Apply conceptual thinking to define situations and strategies', 'Every project is a unique effort to create something new. Except in the most simple projects, this requires the abilities of abstraction and conceptualisation, that is, of breaking down or reducing the subject in question (be it an outcome, plan, requirement, risk, situation or problem) into smaller parts and integrating these into new and useable ideas. The individual must apply conceptual thinking and also leverage able team members. Conceptual thinking also means bearing in mind that problems regularly have multiple causes that relate to each other within a general context, and that different ways of solving problems have different effects on other parts, both in and outside the project.', true, 'High', null, 'Senior baseline / junior target', 'No APM equivalent', 3, 'Derived (priority rule)', 59),
  ('4.4.8.3', '4.4.8', 'Apply analytic techniques to analysing situations, financial and organisational data and trends', 'The individual is able to analyse (or delegate the analysis of) complex situations or problems and find solutions and alternatives. The individual can also analyse and derive useful information and trends from complex sets of data and present or report the findings clearly. Analytical dexterity means having different meth-ods available for detecting a problem’s actual causes and implementing or proposing the correct measures to solve it.', true, 'High', null, 'Senior baseline / junior target. Most assessable in the CE - produces inspectable artefacts.', 'No APM equivalent', 3, 'Derived (priority rule)', 60),
  ('4.4.8.4', '4.4.8', 'Promote and apply creative techniques to find alternatives and solutions', 'Creative techniques should be used to identify solutions. These techniques can be divided into ‘diverging’ techniques and ‘converging’ techniques. When prob-lems arise, the individual needs to judge whether a creative approach is appro-priate or not. Where a creative approach is appropriate, the individual needs to decide which methods to use. After the problem or issue is defined (possibly by using conceptual thinking and/or analytic techniques) there follows a diverging creative stage, to gather possible solutions. A brainstorming session may be appropriate, where members of the team and others in the organisation who might be able to contribute meet to have their ideas captured. Other much-used techniques include mind mapping, storyboarding, visualising, etc. Whatever method is used in finding a creative solution, it involves looking at the issue from different perspectives, combining tools, knowledge, common sense, intuition and experience and applying them. In the following, more analytic, converging stage, possible solutions and their effect on the problem or issue in question are analysed. Converging techniques include weighted selection, force-field analysis, etc. The most promising ideas are then further refined and finally the best concepts/solutions are chosen.', true, 'High', null, 'Senior baseline / junior target', 'No APM equivalent', 3, 'Derived (priority rule)', 61),
  ('4.4.8.5', '4.4.8', 'Promote a holistic view of the project and its context to improve decision-making', 'To promote holistic views means considering a current situation in relation to the full context of the project, such as the enterprise strategies, concurrent activities and/or projects. The individual uses multiple perspectives to judge and deal with situations. The individual recognises the significance of details and can separate the details from the bigger picture. The individual under-stands the connection between the situation and its context and can make or promote decisions based on understanding of a wide array of influences, inter-ests and possibilities. The individual is also able to explain these holistic views to others, both inside and outside the project.', true, 'High', null, 'Senior baseline / junior target', 'No APM equivalent', 3, 'Derived (priority rule)', 62),
  ('4.4.9.1', '4.4.9', 'Identify and analyse the interests of all parties involved in the negotiation', 'Understanding the priorities of the parties to the negotiation is a prerequisite to generating a successful outcome. The individual leading or participating in the negotiations should begin by gathering hard and soft information about inter-ests, needs and expectations of all parties by whatever means are available. Analysis of this information should reveal both priorities and gaps for further research. Priorities of other parties may often have to be assumed.', true, 'High', null, null, 'No APM equivalent', 3, 'Derived (priority rule)', 63),
  ('4.4.9.2', '4.4.9', 'Develop and evaluate options and alternatives with the potential to meet the needs of all parties', 'The individual identifies trade-offs, options and alternative negotiation solu-tions. They are developed during the preparation for negotiation and may be modified during the negotiations as opportunities emerge and the situ-ation changes. The trade-offs, options and alternatives should be tuned to People 107 the interests of the negotiating parties, to be useable during the negotiation process. A best alternative to a negotiated agreement (BATNA) should also be identified.', true, 'High', null, null, 'No APM equivalent', 3, 'Derived (priority rule)', 64),
  ('4.4.9.3', '4.4.9', 'Define a negotiation strategy in line with own objectives that is acceptable to all parties involved', 'The negotiation strategy focuses on what the individual thinks is essential for a successful outcome. Before starting the negotiation, the individual must select the strategy, techniques and tactics that will enable him or her to reach an optimal outcome for the project. The strategy may depend upon factors such as the power balance between the parties, the stakes involved, budget-ary conditions, politics, cultural aspects and the capability of the negotiators. The selected strategy should be appropriate to the interests of the project and not detrimental to relationships with the stakeholders involved. The individual should also consider secondary strategies that cover ‘what if’ scenarios. The strategy also includes who the negotiators will be and what will be their mandate (negotiation scope, freedom, roles and responsibilities). In some cases a choice is also possible about the other party and/or negotiation scope (with whom to negotiate over what). This option should be carefully considered, as this choice might have negative or positive repercussions later on.', true, 'High', null, null, 'No APM equivalent', 3, 'Derived (priority rule)', 65),
  ('4.4.9.4', '4.4.9', 'Reach negotiated agreements with other parties that are in line with own objectives', 'An agreement is reached through negotiation using the identified strategies, tools and tactics without alienating the other parties involved. Negotiation may occur over an extended timeframe and may proceed in phases. A satisfactory agreement is one in which all parties are reasonably satisfied with the result, will honour their commitments, think the other parties negotiated fairly and feel respected and will negotiate again. If an agreement is not achievable or the possible outcomes are not acceptable, the BATNA is implemented. The best possible solution is often one that is sustainable and provides the best long-term results for all parties. There may be specific situations where this is not possible or preferable and a compromise may be required to meet one’s desired outcome. In many situations, the agreed outcomes are documented for future reference.', true, 'High', null, 'BATNA concept - links to Practice 9 Procurement.', 'No APM equivalent', 3, 'Derived (priority rule)', 66),
  ('4.4.9.5', '4.4.9', 'Detect and exploit additional selling and acquisition possibilities', 'The individual is constantly striving to realise the processes and agreed out-comes faster, better and/or cheaper. This means that the individual has to have a keen eye for opportunities to realise this aim. Depending on the situation, this may for instance mean searching for new suppliers or renegotiating old agree-ments, looking for ways to offer services to new clients, negotiating better con-ditions with stakeholders or inviting teams or team members to realise tasks sooner, better and/or cheaper. Negotiating will occur after the new opportuni-ties are identified. The desired state should be seen in the light of the best interests of the project and the organisation. Is the organisation best served with the present situation or with efforts to improve it? In considering this, the individual is aware People 109 that negotiations also take up time and effort and that present relationships with negotiation partners may be affected.', true, 'High', null, 'Guidance block written - title reads commercially, measures are generic value-seeking.', 'No APM equivalent', 3, 'Derived (priority rule)', 67),
  ('4.4.10.1', '4.4.10', 'Evaluate all decisions and actions against their impact on project success and the objectives of the organisation', 'In everything the individual does, he or she is guided by the goal of the project, which is to achieve success. This goal underpins all the individual’s decisions and actions. Every choice may have negative or positive repercussions later on, so it needs to be carefully considered. The individual will judge new developments by the following criteria: Will this realise (or threaten) the objective or result, or make the process faster, cheaper and/or better and so more of a success?', true, 'High', null, null, 'No APM equivalent', 3, 'Derived (priority rule)', 68),
  ('4.4.10.2', '4.4.10', 'Balance needs and means to optimise outcomes and success', 'Every choice entails allocating or denying means (resources, money, time, attention) to certain actions (tasks, decisions, questions, problems, etc) based on perceived needs. In order to optimise means allocation the individual must have a clear picture of the priorities of the project. Based on that, the individual must prioritise the various needs and balance the allocation of means based on the priorities. This may mean giving no attention or means at this stage to perceived challenges or problems, as the individual judges other needs to have greater priority.', true, 'High', null, '''Says no with a rationale'' - key matrix control with 7 PMs competing for shared specialists.', 'No APM equivalent', 3, 'Derived (priority rule)', 69),
  ('4.4.10.3', '4.4.10', 'Create and maintain a healthy, safe and productive working environment', 'Ensuring a healthy, safe and productive working environment means providing the team with all of the required means and limiting distractions so that the team can focus on working efficiently. The individual acts as a filter and a buffer between the environment and the team members, absorbing uncertainties and ambiguities that could disturb progress and their results orientation. In addi-tion, the individual facilitates the team with the necessary infrastructure and resources.', true, 'High', null, null, 'No APM equivalent', 3, 'Derived (priority rule)', 70),
  ('4.4.10.4', '4.4.10', 'Promote and ‘sell’ the project, its processes and outcomes', 'The individual often has to act as an ambassador and advocate for the project, explaining the why, how and what (its objectives, approach, processes and agreed outcomes) to all concerned parties. The promotion reinforces the results orien-tation by making clear the outcomes and the need for the outcomes. This can be done by regular reporting and stakeholder engagement, but at least as often is achieved by formal and informal communication and marketing, varying from coffee-corner talks with team members to formal presentations. This marketing or ‘selling’ the project is part and parcel of every communication made by the individual. The individual preferably also invites team members, the project owner and others to join in the marketing effort.', true, 'High', null, null, 'No APM equivalent', 3, 'Derived (priority rule)', 71),
  ('4.4.10.5', '4.4.10', 'Deliver results and get acceptance', 'The litmus test of every individual is whether they can deliver, or realise what was promised, to get results. This quality requires a clear resource plan, planned outcomes, a strong belief in personal capacity and that of the team to overcome obstacles and problems, plus the overarching desire to deliver. The individual knows that being effective is not the same as being efficient. Effectiveness is realising the planned goals (e.g. realising the agreed outcomes within agreed deadlines, budget, quality, etc), while efficiency is doing so with the least necessary cost and time (measured, for instance, by comparing the planned number of people against actuals). Therefore, the individual needs to constantly search for means to realise the agreed results faster, cheaper or better. Finally, the individual needs to be able to rally people to the cause while keeping to the planned level of productivity, knows what the individual can and cannot do (and get away with) in a specific situation and organisation and what is politically appropriate.', true, 'High', null, 'ICB4 calls this the litmus test for delivery capability.', 'No APM equivalent', 3, 'Derived (priority rule)', 72),
  ('4.5.1.1', '4.5.1', 'Acknowledge, prioritise and review success criteria', 'Success criteria are measures that stakeholders use to rate and judge the success of the project. These criteria can be both formal and informal. Formal criteria address the stated objectives of the project. To achieve these goals and objectives within the agreed constraints (e.g. strategic goals, tactical and operational objectives) is one – but just one – part of project success. Informal criteria by which interested parties evaluate the outcome are also important. These factors may include the true reasons why a project is started, supported, thwarted or ended. Success criteria also address the interaction with the larger context – the personal or group interests that are influenced by the project or its result, depending on how a project supports or conflicts with other projects and programmes, activities, goals, resources, etc. The individual collects, acknowledges, prioritises and completes both formal and informal success criteria for the project. Not only the formal criteria, but also the informal ones, need to be taken seriously by the individual, as they will significantly influence the willingness of interested parties to support and coop-erate with the project and so directly influence its success. The success criteria play a crucial role in defining the approach. For instance, if the main criterion is the quality of the end product, quality processes, quality reviews and assurance and quality consideration will play an important role in the chosen approach. This approach would differ substantially from a project with the focus on time (speed of delivery) or budget. Success factors are elements that individuals can incorporate into their project to increase the likelihood of meeting the success criteria and achieving a successful outcome. These factors may come from very different sources and take different shapes. They vary from using (or avoiding) specific tools, methods or techniques, selecting specific resources, organisation setup, stages, reporting and communication means and styles, quality meth-ods, etc. During the course of every project the relative importance of success factors and criteria may change, due to contextual or social aspects and the dynamics of the project itself. Therefore the individual periodically checks and assesses the actuality and relative importance of the success criteria and – when necessary – makes due changes in the approach in order to attain success. These changes may even include advising the organisation to prematurely end the project. Practice 119', true, 'High', null, 'Formal/informal success criteria split is the valuable half.', '1 Life cycles', 2, 'APM (published)', 73),
  ('4.5.1.2', '4.5.1', 'Review, apply and exchange lessons learned from and with other projects', 'At the start of the project, the individual gathers lessons learned from previous projects (both from his or her own organisation(s) and from the wider com-munity, including research and benchmarks) and applies relevant lessons in the present project. Periodically and at the end of the project, the individual (with the team and relevant stakeholders) evaluates the approach and gath-ers lessons learned from the current project. They shall be shared within the organisation. The individual knows and uses the different methods and tools for distributing lessons learned in the organisation (e.g. strategic project office, knowledge base, internal social network, etc).', true, 'High', null, 'Lessons-learned cluster - primary instance. No APM equivalent (knowledge management).', 'No APM equivalent', 3, 'Derived (priority rule)', 74),
  ('4.5.1.3', '4.5.1', 'Determine complexity and its consequences for the approach 119 © 2015 International Project Management Association', 'To properly select an appropriate approach, the individual has to take into account the specific complexity of the project – the complexity of the agreed outcomes and/or of the project processes required. The complexity may have many causes and sources. It may be that the outcomes or necessary internal processes of the project are innovative, technically complex and/or strongly intertwined. It may be that the project involves many teams, people, suppliers, dependencies, etc. It may be that the context of the project is complex, for instance many stakeholders with varying interests, many interfaces with other processes, projects, programmes, etc. Timelines may be short, budgets limited, outcomes crucial for the organisation, etc. All these internal and external factors have to be taken into account by the individ-ual because they play an important role in defining the optimal approach for the project.', true, 'High', null, 'Guidance block written - KIB has no formal complexity-assessment method. ICCPM standards are the source if one is adopted.', '1 Life cycles', 2, 'APM (published)', 75),
  ('4.5.1.4', '4.5.1', 'Select and review the overall project management approach', 'At the very beginning of the project, the individual chooses an approach that has the highest probability of success, given the constraints of contextual influ-ences and demands, complexity of the project, lessons learned, known success criteria and available success factors. The approach may contain a vision (main principles) and an architecture for the project to reach success. This approach may include a high-level definition (or modification) of scope, quality aspects, organisation, communication, documentation, planning and stakeholder approach, choice of resources, risk tolerance, management and performance criteria, etc. The individual reviews the approach periodically, because many of the con-textual and social influences may change over the lifecycle of the project.', true, 'High', null, 'Phase 2: word around tailoring within KIB methodology if PM latitude is bounded.', '1 Life cycles', 2, 'APM (published)', 76),
  ('4.5.1.5', '4.5.1', 'Design the project execution architecture', 'Based on the selected approach, the individual draws a high-level ‘charcoal sketch’, a blueprint or even architecture for the project. This high-level plan will be detailed later via formalised plans, but the basic design only considers the essential choices (such as make or buy, waterfall or iterative, internal resources or external, what tools and methods to use, etc) and the consequences of each choice for success. These choices made by the individual also include the best way to lead the project. Project management success is an essential part of, and prerequisite for, project success. In some circumstances, this may mean choosing a strong profile as leader, or, given other criteria, act as ‘first among equals’ towards the team or the stakeholders. Often this choice will vary with circumstances and environments and/or the phase the project has reached. In the course of the project the individual periodically evaluates (aspects of) the design, taking into consideration the development and progress of the project, changing contextual influences and demands, known success criteria and avail-able success factors. This often leads to minor or major changes in the chosen execution architecture.', true, 'High', null, null, '1 Life cycles', 2, 'APM (published)', 77),
  ('4.5.2.1', '4.5.2', 'Define and develop the project goal hierarchy', 'Every project is started because of the needs and goals of the organisation. From these organisational goals the project goals are derived: high-level statements that provide the rationale and overall context for what the project is trying to achieve. In their turn, from these project goals, the project objectives are derived: lower level statements that describe the specific, tangible products and delivera-bles that the project will deliver. This goal hierarchy is influenced and determined both by contextual factors and by elements such as specific stakeholder needs and requirements. The project mission statement explains the strategic reasons for starting this project. Secondly the project objectives are defined, which are to realise the project outcomes within the constraints of acceptable risk, agreed timeframes and budget. A third category of goals is potential positive side effects (consequential benefits). Examples include gaining new knowledge, strengthening relationships and experience with outsourcing.', true, 'High', null, null, '19 Requirements management', 3, 'APM (published)', 78),
  ('4.5.2.2', '4.5.2', 'Identify and analyse the project stakeholder needs and requirements', 'To be competent in identifying stakeholder needs and requirements requires knowledge of, and communication with, the permanent organisation and stake-holders including customers and end users. Needs and expectations are not the same as stated requirements; often needs are not formulated, for instance because they are obvious, not conscious or hidden. As far as possible, needs should become explicit and be translated into requirements. These requirements have to be analysed, for instance using value management techniques.', true, 'High', null, 'Requirements traceability stated as capability, not as a mandated artefact - the reason ICB4 beat PMCD.', '19 Requirements management', 3, 'APM (published)', 79),
  ('4.5.2.3', '4.5.2', 'Prioritise and decide on requirements and acceptance criteria', 'After analysis, the requirements have to be prioritised. Priorities are determined by the project sponsor (owner), top managers or external customers. The me-thods for documenting the requirements must be defined (e.g. a requirement specification which can be more or less detailed or a product-backlog contain-ing user stories). Requirements should be translated into acceptance criteria against which the deliverables can be tested. Practice 125', true, 'High', null, 'Measures correctly scope the PM to facilitating; the sponsor decides.', '19 Requirements management', 3, 'APM (published)', 80),
  ('4.5.3.1', '4.5.3', 'Define the project deliverables', 'The project deliverables are the tangible and intangible assets (results, services, outputs) of the project by means of which the expected effects and benefits are to be realised. Moreover, the project deliverables are the measurable results by which the project management success is judged. A deliverable is a tangible or intangible object produced as a result of the project that is intended to be delivered to a customer (either internal or external). The goal hierarchy, men-tioned and dealt with in competence element ‘requirements and objectives’, is extended and completed here. The project deliverables and sub-deliverables are placed in the bottom section of the hierarchy. In the graphical presentation of the hierarchy, lines are drawn between goals and deliverables to indicate links and interrelationships.', true, 'High', null, null, '22 Integrated planning', 3, 'APM (published)', 81),
  ('4.5.3.2', '4.5.3', 'Structure the project scope', 'Structuring the scope entails a systematic division of the entire project content into sub-tasks and work elements. This project structure or work breakdown structure (WBS) includes an overall division followed by sub-divisions. A graph-ical presentation of the WBS is typically a tree structure with a number of step-wise-divided sub-levels depending on the desired level of details of task or work elements. Various principles can be used for creating the WBS. One principle is that the overall structure reflects all the sub-products necessary to deliver the project results such as analysis, design, development and testing. Another prin-ciple for structuring the scope may reflect the different functional or physical structures of the project results. Irrespective of the approach, structuring the project scope is a valuable way of creating an overview of the project content. Clarifying and structuring the scope may therefore also be relevant with an iter-ative (e.g. agile) approach, although the level of detail in the WBS is typically not as deep as with a linear or sequential approach.', true, 'High', null, 'Contains the ''when a full WBS is inappropriate under agile'' judgement - suits a hybrid PMO.', '22 Integrated planning', 3, 'APM (published)', 82),
  ('4.5.3.3', '4.5.3', 'Define the work packages of the project', 'All the lowest elements in the WBS represent a work package with well defined boundaries. In essence, clear boundaries are indeed the overall success criterion of an effective WBS. The definition of a work package includes a description of the work to be performed, the work objectives, cost, resource need and duration. If the duration, cost and/or resource need is not yet clear, it is named a planning Practice 129 package. With an iterative (e.g. agile) approach, a work package in a software development project is typically referred to as a user story. The same guidelines may apply to the definition of a user story as to a work package. Control accounts are groups of work packages typically used for reporting.', true, 'High', null, null, '22 Integrated planning', 3, 'APM (published)', 83),
  ('4.5.3.4', '4.5.3', 'Establish and maintain scope configuration', 'Scope configuration management helps to minimise deficiencies, errors and unin-tended scope creep. Scope configuration management is meant to ensure that the scope is aligned with the agreed stakeholder needs and requirements and that all resources assigned to the project are working with the same version of the prod-uct. Projects operate within a dynamic environment whereby changes occur and need to be captured and managed, as opposed to being treated as obstacles and as something hampering project success. A scope configuration mindset is char-acteristic of an iterative (e.g. agile) approach to the project and is value-driven as opposed to plan- or task-driven. Scope configuration management is often a continuous process.', true, 'High', null, 'Earned value appears here - confirm whether KIB uses EVM.', '22 Integrated planning', 3, 'APM (published)', 84),
  ('4.5.4.1', '4.5.4', 'Establish the activities required to deliver the project', 'Based on an analysis of the deliverables and/or requirements, preferably through a work breakdown structure (WBS), the activities necessary to achieve agreed results are defined. With iterative planning, the individual focuses on defining only the activities necessary for the agreed deliverables of the current iteration.', true, 'High', null, null, '23 Schedule management', 3, 'APM (published)', 85),
  ('4.5.4.2', '4.5.4', 'Determine the work effort and duration of activities', 'For each activity the work effort and duration necessary for realisation has to be determined. This includes determining what resources and resource compe-tences, and how much, are required for each activity. When several resources (both material and personnel) are available, a balance has to be found between quality, cost and speed of delivery. This balance depends on the project success criteria and requirements.', true, 'High', null, null, '23 Schedule management', 3, 'APM (published)', 86),
  ('4.5.4.3', '4.5.4', 'Decide on schedule and stage approach', 'Depending on the chosen approach for the project (e.g. waterfall or iterative planning), a decision has to be made on the number, content, length and deliv-erables of the stages (or phases). The selection of a particular path very much depends on the specifics of the project success criteria and requirements, guide-lines in the organisation and other contextual factors, uncertainty, etc. For instance, higher uncertainties may lead to shorter phases.', true, 'High', null, null, '23 Schedule management', 3, 'APM (published)', 87),
  ('4.5.4.4', '4.5.4', 'Sequence project activities and create a schedule', 'Many activities are dependent on availability or on previous realisation of other work packages or activities. Based on these known dependencies and the calculated duration of each activity, an activity flow can be defined. From this, the critical path can be calculated. This critical path may be influenced by the availability of resources. The activity of levelling can optimise the assignment of resources in the planning and may influence the critical path.', true, 'High', null, 'Most objectively assessable control in Practice - critical path and resource levelling.', '23 Schedule management', 3, 'APM (published)', 88),
  ('4.5.4.5', '4.5.4', 'Monitor progress against the schedule and make any necessary adjustments', 'As soon as the planning is done and activities are started, control systems (such as time-writing systems and progress meetings) should be in place. Various methods, such as earned value analysis, can be used to measure realised prog-ress versus baseline. A project plan may be subject to many disturbances, result-ing in necessary adjustments. These may come from various sources (changes in deliverables, requirements, scarcity of resources or money or late or off-spec deliveries) and may demand re-planning. Periodically, the schedule should be compared against the baseline and, if necessary, adjustments should be made.', true, 'High', null, 'Earned value appears here - confirm whether KIB uses EVM.', '23 Schedule management', 3, 'APM (published)', 89),
  ('4.5.5.1', '4.5.5', 'Assess and determine the needs of stakeholders relating to information and documentation', 'The individual knows about the close link between information and organisation and that needs for information may also determine the need for specific organisational structures. For example, in organisations practising outsourc-ing with one or more virtual teams, the need for a high level of information is evident. Care must be taken in deciding who gets what information – over-whelming people with too much information must be avoided. Interested parties in general should receive only the information they need and in a suitable form. The individual must discern the needs for formal and informal information/doc-umentation. Knowing the corporate structures and processes will automatically outline part of the formal information and documentation (specifications, plans, budgets, reports and more). It is the responsibility of the individual to ensure that the information and organisational needs are defined.', true, 'High', null, null, '2 Governance arrangements', 3, 'APM (published)', 90),
  ('4.5.5.2', '4.5.5', 'Define the structure, roles and responsibilities within the project', 'The individual can structure the temporary organisation in various ways and is aware of the influences from governance and contextual characteristics such as strategy, structures and processes, power and interest, standards and regula-tions, culture and values. Applied technologies, anticipated solutions, required competences and the geographical location of the participant will also have a high impact on the design of the organisational structure. The individual knows about the advantages and disadvantages of different structures and is also capable of designing, staffing and implementing the temporary organisation. If necessary, an appropriate governance framework and structure will be estab-lished for the project, as well as for all subordinate projects (if any). As part of this framework, roles and responsibilities are clearly defined and decision-mak-ing authorities and delegation levels are also identified.', true, 'High', null, 'Contains the matrix keystone measure: record the difference between functional and project authorities.', '2 Governance arrangements', 3, 'APM (published)', 91),
  ('4.5.5.3', '4.5.5', 'Establish infrastructure, processes and systems for information flow', 'The individual knows how to establish communication processes including roles and responsibilities and all rules and guidelines for what internal information to communicate and how. Additionally, appropriate systems and methods are implemented to support the governance arrangements. How to limit and/ Practice 137 or prevent redundant information is a key success criterion for establishing efficient information processes – and information must be consistent and unambiguous. Information infrastructures cover the systems, means and methods required for documenting, storing and communicating the internal information. Information infrastructures and IT are inseparable in a modern organisation and consequently, being aware of the corporate IT systems and policies is important for the individual.', true, 'High', null, 'Decision documentation - audit trail matters under CBK supervision.', '2 Governance arrangements', 3, 'APM (published)', 92),
  ('4.5.5.4', '4.5.5', 'Implement, monitor and maintain the organisation of the project', 'The individual knows how to manage the project organisation, including implementation, monitoring and maintenance of the temporary organisation. Implementation means to make the initially defined organisational structure operational – to make it work. However, implementation also includes changes to the organisation when necessary. The need for changes to the temporary organisation should be anticipated as the project evolves. Any given structure of an organisation is valid only for a limited period of time. In particular, changes in contextual factors (such as strategy and/or power and interest) tend to influence the temporary organisation and call for changes or minor adjustments. Through the ongoing monitoring of the project’s environment, the individual has to proactively envisage the need for changes to the temporary organisation.', true, 'Medium', 'Retained at Medium. The monitoring and adjusting content is genuine PM work - reshaping workstreams, roles and decision rights as a project evolves - but overlaps 4.5.5.2, which carries the design of structure and authorities at High.', 'Guidance block written. Revisit for further clarification.', '2 Governance arrangements', 3, 'APM (published)', 93),
  ('4.5.6.1', '4.5.6', 'Develop and monitor the implementation of and revise a quality management plan for the project', 'The purpose of managing the quality is to plan and guarantee the quality requirements and standards applicable to the project and the project deliv-erables. Planning of the quality includes determining and agreeing with the project sponsor/owner and other key stakeholders on the quality objectives to be achieved. It includes defining indicators and setting quality target values for those indicators in the project at hand. It includes establishing the tools, proce-dures, techniques and resources necessary to achieve the quality objectives. It also includes developing the quality plan, including type of reviews, responsibil-ities, participants and a time schedule developed in accordance with the overall project time schedule. It includes the monitoring and assessment of the tasks defined in the plan and closing the quality tasks, like all others in the project.', true, 'High', null, null, '21 Quality management', 3, 'APM (published)', 94),
  ('4.5.6.2', '4.5.6', 'Review the project and its deliverables to ensure that they continue to meet the requirements of the quality management plan', 'The purpose of performing quality management is to continuously review the project and the project deliverables. It encompasses all processes, tools, pro-cedures, techniques and resources necessary to meet the defined and planned quality objectives. The quality management process ensures that the quality goals to be achieved are communicated, understood, accepted and followed by the members of the temporary project organisation. The process also includes executing the quality plan as the project progresses, revising it and delivering indicators of its fulfilment. Quality audits can be performed by various parties, by people from inside or outside the temporary project organisation, or even by external parties such as customers. Audits serve a relevant and important purpose, as they determine the performance of the quality process, the quality control and their output must be analysed to determine the need for corrective and preventive actions or change requests. Quality audits can also be used as a means of reporting progress.', true, 'Medium', 'Reviewing performance, communicating quality objectives and analysing audit findings are PM work. ''Performs a quality audit'' asks the PM to audit their own project - the independence problem that removed Assurance from the APM track.', null, '8 Reviews', 3, 'APM (published)', 95),
  ('4.5.6.3', '4.5.6', 'Verify the achievement of project quality objectives and recommend any necessary corrective and/or preventive actions', 'The purpose of performing verification is to determine whether the established project quality requirements, objectives and standards are being met, in each phase of the project development. The process of performing verification is done during the entire project lifecycle, usually at the end of each phase. It includes establishing whether the quality of the project deliverables and processes is being met and detecting defects by using established tools, procedures and techniques. It also includes analysing possible causes of defects, determining the appropri-ate corrective and preventive actions and formulating recommendable change requests. Finally it includes communicating the recommended corrective and pre-ventive actions and change requests to relevant members of both the temporary and permanent project organisation. Parties representing the permanent organisation may perform verification activities. It has been proven that it is more cost-efficient to perform verification at early stages of the development of the project, instead of leaving verification to the end of the project.', true, 'High', null, 'Verb throughout is ''recommend'', not ''impose'' - correctly scoped.', '21 Quality management', 3, 'APM (published)', 96),
  ('4.5.6.4', '4.5.6', 'Plan and organise the validation of project outcomes', 'It is often not feasible to assess whether a specific, measurable, achievable and timed goal or objective is met or not, or the degree or percentage to which the goal or objective is met. The anticipated value gained from a project by means of the project deliverables is an example of this, as it is often difficult to measure and verify explicitly. In such cases, validation is a feasible way to determine the quality level of the value gained from the project outcome. The goal of validation is to create a formal acceptance by the client of the project. Validation is typically performed by either the permanent organisation or other external parties (e.g. customers) and rarely by the temporary organisation itself. However, it is the responsibility of the individual to plan and organise the validation. Validation can be done in various ways: in a single event or as a pro-cess to ensure continuous validation.', true, 'High', null, 'Formal acceptance from the business - common failure point.', '21 Quality management', 3, 'APM (published)', 97),
  ('4.5.6.5', '4.5.6', 'Ensure quality throughout the project', 'Based upon the quality procedures both of the organisations and the suppli-ers, a quality approach for the project is chosen and implemented. It should be fit for purpose and implementable with relative ease. Adaptation, integration and implementation will require dealing with several organisations (or parts of organisations) who all prefer doing it their own way. Once implemented, regu-lar check-ups and improvements need to take place to maintain the fitness for purpose. Since quality is about people, not just about processes, special attention should be paid to quality awareness and ‘the right quality for this project’.', true, 'High', null, null, '21 Quality management', 3, 'APM (published)', 98),
  ('4.5.7.1', '4.5.7', 'Estimate project costs', 'The individual estimates or, if possible, calculates the costs needed to execute the project. Direct costs, such as labour hours, materials, investments, ongoing operating costs, travel expenses, training costs and indirect costs, such as over-head fees or licences or even opportunity costs — all have to be identified and estimated. Cost estimation includes the utilisation of a cost breakdown structure (possibly derived from a WBS) or other appropriate methods, in order to catego-rise the estimated costs. Cost estimation is mostly done ‘top-down’, based on the experience of subject matter experts, historical data, group estimation, ‘bottom-up’ or other domain-specific techniques. Cost targets for the whole project or single cost categories might be defined ‘top-down’ or ‘bottom-up’. When doing the calculation the individual also needs to be aware of any normative cost stan-dards which could help in doing the more accurate calculation (e.g. engineering industry cost calculation standards). Furthermore, dependent on the specifics of the industry and the nature of the goods or services sold on the market, the indi-vidual needs to be able to apply the appropriate cost calculation technique.', true, 'High', null, null, '26 Budgeting and cost control', 3, 'APM (published)', 99),
  ('4.5.7.2', '4.5.7', 'Establish the project budget', 'Establishing budgets is closely related to estimating costs. Based on the cost estimation, the individual defines the budgets on appropriate levels of the cost breakdown structure (CBS). A close link to the WBS will ensure that it is possible to identify when costs will be expended and on what. The individual gets an over-view of the time-related expenditure of funds. By taking not only the outflows but also the inflows of cash into account, a cash flow can be forecast even at an early stage of the project. The costs should be connected with time, in order to check whether the costs can be secured by the funding function of the organisation and, if not, to ensure that the appropriate adjustments are made. The project budget should include contingencies that are held in reserve to fund uncertainties, risks, claims or cost overruns.', true, 'Medium', 'Budget-setting at KIB is bounded - the envelope is approved through business case governance rather than set by the project manager. Applicable behaviours are building the budget plan, scenario work and contingency planning within that envelope; ''sets the final budget'' overstates PM authority.', 'Senior baseline / junior target', '26 Budgeting and cost control', 3, 'APM (published)', 100),
  ('4.5.7.3', '4.5.7', 'Secure project funding', 'The individual ensures the availability of financial resources at the right time to make sure costs are covered. The individual must follow the organisational approval processes (if in place) to get the financial needs granted. Discussions around the funding may be influenced by political circumstances. In this case, the individual may need to promote the project to potential internal and external sponsors. Even though the financing part should fall under the accountability of the project sponsor, usually the project manager needs to determine the finance structure.', true, 'Medium', 'Two of four measures apply - handling organisational approval processes and negotiating with sponsors to secure budget. Establishing funding strategies and identifying sources of funds describe external project financing, which does not arise for internally funded KIB initiatives.', null, '26 Budgeting and cost control', 3, 'APM (published)', 101),
  ('4.5.7.4', '4.5.7', 'Develop, establish and maintain a financial management and reporting system for the project', 'A financial management and reporting system must be established so that an overview of the financial situation and status of the project is available at any time. The financial management system links the project cost structure, the organisational cost structure and the time schedule. It includes not only processes but also roles and responsibilities (e.g. payment authorisations). Financial reports are the visual output of the management system. The indi-vidual establishes performance management indicators to monitor the rela-tionships between cost and progress (e.g. cost to complete and earned value). Bases for these indicators include the mapping of cost structures and project structures. In most organisations the project financial management is closely linked to organisational accounting and controlling processes. If in place, mandatory methods and instruments may have to be used, but adapted to the specific needs of the project. If not in place, a project-specific financial man-agement system must be defined and applied.', true, 'High', null, 'Earned value referenced - confirm whether KIB uses EVM. Islamic-banking language review at Phase 2.', '4 Financial management', 3, 'APM (published)', 102),
  ('4.5.7.5', '4.5.7', 'Monitor project financials in order to identify and correct deviations from the project plan', 'The goal of financial controlling is to identify deviations from the plan to enable timely reactions. The individual monitors planned and actual costs, liabilities and expected costs of the project as well as the cash flow. After analysing the deviation and its possible causes, necessary actions are taken. Planned costs are derived from the latest project plan (latest approved budget updated with changes). The actual costs come from the actuals monitored by the project team. However, the real figures are often provided by the organisational accounting. They encompass expenses for all planned cost items, such as labour hours, travel costs or bills, and any other liabilities covered by the procurement agreement and not stated in the cost calculation (e.g. material transport, consultancies, etc). The liabilities are often included in cost controlling. Liabilities are expenses bound by purchase orders but not yet paid. Comparing actual costs to planned costs is especially informative when the costs are related to the project progress. The individual uses the financial performance indicators to monitor the relationships between planned cost, actual cost, actual work done and progress trends (e.g. earned value indicators, SPI, CPI, etc). Thus the individual analyses the current project performance by controlling the financial resources and manages any underspending or overspending. Finally, the individual uses the performance indicators to make forecasts of the future project performance. If cost breaches have been forecast, the individual needs to report in accordance with the project’s organisation and governance and suggest an appropriate mitigation plan.', true, 'High', null, 'Escalation control for money - routes through governance, correctly scoped.', '4 Financial management', 3, 'APM (published)', 103),
  ('4.5.8.1', '4.5.8', 'Develop strategic resource plan to deliver the project', 'The strategic resource plan stipulates who is responsible for which part of the resource definition, resource allocation, resource development, resource distri-bution and resource freeing. Responsibilities may lie with the programme man-ager if the project is part of a programme, with the constituent organisations, with resource managers or with the underlying projects. The strategic resource plan needs to be in line with the schedule. The individual develops, organises and assesses a plan and adapts it to changes whenever needed.', true, 'Medium', 'Two of four measures are project-level resource forecasting and baselining, which feed 4.5.8.2. The other two - analysing the organisation''s resource capacity and identifying trends, and coordinating with portfolio management processes - are portfolio-level work, matching the basis on which APM C25 Resource capacity planning was excluded from the PM track.', 'Target is Aware - two levels below its CE. APM independently corroborates the scoping judgement.', '25 Resource capacity planning', 1, 'APM (published)', 104),
  ('4.5.8.2', '4.5.8', 'Define the quality and quantity of resources required', 'The individual must identify the resources (type, quantity and quality) that are needed to successfully deliver the project results, based on the strategic resource plan. Resources include people, expertise, facilities, equipment, materials, infrastructure, tools, non-financial funds or services. After identifying these resource needs, a more detailed analysis is conducted that defines when the resources need to be available and of what quality and in what amount they are needed. This may result in a detailed operational resource plan(s).', true, 'High', null, null, '24 Resource management', 3, 'APM (published)', 105),
  ('4.5.8.3', '4.5.8', 'Identify the potential sources of resources and negotiate their acquisition', 'Once the needed resources have been defined, the right resource providers must be identified. Resources can be sourced with the organisations, or with commercial parties. Many organisations provide sourcing guidelines that have to be followed. Especially when ‘make or buy’ decisions have to be taken, the individual must rely on formal and informal networks. A good knowledge of the organisation, as well as a broad overview of the markets for resources, is necessary, in order to create and decide on sourcing alternatives. Obtaining external resources is very different from allocating internal resources. While acquiring internal resources is merely a question of availability and quality, the costs for external resources also have to be negotiated.', true, 'High', null, 'Phase 2: ''make or buy'' and ''sourcing strategy'' measures describe governance decisions - address in guidance.', '24 Resource management', 3, 'APM (published)', 106),
  ('4.5.8.4', '4.5.8', 'Allocate and distribute resources according to defined need', 'Resource allocation means assigning resources to specific projects or activities. This enables monitoring, controlling and management of the resources, their results and the related costs. Allocating resources is in general closely linked to scheduling. Changes in the schedule and changes in the resource availabil-ity or quality often affect each other. Some specialities have to be taken into account when human resources are allocated, as productivity or learning speed may differ between individuals. The resources that are contracted need to be distributed within the project according to needs and according to the strategic resource plan. The conditions under which resources are contracted need to be adhered to. When there are conflicting resource needs, the individual needs to consider all options and come up with the best way to handle these needs, based on priorities, urgency, or other criteria.', true, 'High', null, '''Negotiates resource conflicts'' - the matrix control in this CE.', '24 Resource management', 3, 'APM (published)', 107),
  ('4.5.8.5', '4.5.8', 'Evaluate resource usage and take any necessary corrective actions © 2015 International Project Management Association', 'All the relevant resources parameters and indicators must be monitored to ensure the proper usage of resources. Evaluating resources entails applying a systematic approach in order to derive productivity numbers. When required, the individual should take corrective action. In the case of over- or under-estimation new assignments must be checked. The individual should also regularly evaluate the quality and availability of assigned resources. In the case of external resources, consultations with suppli-ers and other contractors may be necessary in order to improve or exchange the resource. The performance of people may have to be improved. These people Practice 153 would then need development, coaching and specific training measures. This should be negotiated and coordinated with the resource suppliers. The individual is responsible for allocating and re-allocating critical resources, even beyond the resources for which the individual is directly responsible.', true, 'High', null, 'Routes skill shortages through the line manager - correct scoping for KIB.', '24 Resource management', 3, 'APM (published)', 108),
  ('4.5.9.1', '4.5.9', 'Agree on procurement needs, options and processes', 'Needs and options identification is the process of determining which resources or services are to be procured or for which aspects of the project that partners will be acquired. This may result from shortage or lack of internal availability or a conscious choice to acquire resources externally (make or buy strategy). The procurement options, routes, acquisition requirements, tender docu-ments and selection criteria must be agreed on. The individual manages this pro-cess, often in close cooperation with or delegated to specialised departments or the management, ensuring that relevant information is made available and that the relevant internal and external stakeholders are informed.', true, 'High', null, null, '7 Procurement', 2, 'APM (published)', 109),
  ('4.5.9.2', '4.5.9', 'Contribute to the evaluation and selection of suppliers and partners', 'The individual ensures that the possible partner organisation and/or other experts, suppliers or partners are identified, evaluated and selected. In this selection process, the defined tender documents and selection criteria are applied (or, if no supplier is able to deliver in accordance with the terms of reference, reformulated). These tender and selection criteria and the procure-ment process may be subject to formal regulations (e.g. in Roman-Germanic law countries). The selection process itself often includes various steps, such as requests for information (RFI) and requests for proposal (RFP) or requests for quotation (RFQ). If the procurement leads to any partnership models and the bidding process is not being used, the individual shall follow a careful process to safeguard the quality of the selection of partners. Practice 157', true, 'High', null, 'Phase 2: partnership-models measure (joint ventures) is out of scope - address in guidance.', '7 Procurement', 2, 'APM (published)', 110),
  ('4.5.9.3', '4.5.9', 'Contribute to the negotiation and agreement of contractual terms and conditions that meet project objectives', 'Once the supplier or partner is selected, a negotiation process may follow, in order to reach agreement about the contractual terms and conditions. The indi-vidual oversees this process and makes sure that the negotiators have a clear mandate, in close cooperation with purchasing and/or legal specialists. The contracts may vary in form, level of detail, contract duration, terms and conditions, penalties, applicable law and many other aspects. The individual takes care that these aspects closely relate to and serve the objectives of the project and the organisation. When the contract negotiations are complex and long-lasting, sometimes a precontractual arrangement is agreed on to make preliminary work or deliveries possible.', true, 'High', null, 'Phase 2: price-negotiation measure sits with procurement and legal - address in guidance.', '7 Procurement', 2, 'APM (published)', 111),
  ('4.5.9.4', '4.5.9', 'Supervise the execution of contracts, address issues and seek redress where necessary', 'Contract performance means the continuous supervision of the supplier or partner once the contract has been established, to ensure the correct and timely execution of the contract. In case of deviations from the contract, the individ-ual has to take action or escalate, whenever necessary, within his or her own organisation. If one or more of the contract terms (such as delivery time, qual-ity, etc) are not met, the individual must take action to address this issue and if possible solve it. This may include various techniques, from soft notices to serious renegotiations, and the individual needs to know when to use each of these. After the techniques are applied, if the contract partner remains in default, the individ-ual should take or invite a decision as to whether a penalty should be claimed or whether to seek redress from the contract partner by other means. This situation may include legal action or involve legal specialists, always consulting the man-agement in order to align with the strategic procurement long-term policies.', true, 'High', null, 'Islamic-banking language review at Phase 2 (penalties, claims).', '27 Contract management', 2, 'APM (published)', 112),
  ('4.5.10.1', '4.5.10', 'Start the project and develop and get agreement on the project management plan', 'The first phase of every project is essential, as it provides the basis for a successful project. This preparation phase is frequently characterised by uncertainty, with information that is sketchy or not yet available. Stakeholder requirements may be only roughly defined, their expectations unrealistic and timeframe undeliverable, while early optimism and enthusiasm needs to be tempered with reality. A proactive project management style, a well prepared and effectively managed start-up workshop and the recruitment of the right project team personnel can improve the chances of a successful project. One or more start-up workshops should focus on developing the project charter and preparing the project management plan, setting out the team roles and critical path for the project. The individual prepares and plans a project. Starting from the predefined high-level design, the individual gathers, analyses, values and prioritises enough information from the stakeholders and experts to fine-tune this approach and make an overall project management plan. This plan will be based on information and choices about requirements and quality, agreed deliverables and constraints, organisation and communication structures, necessary resources and budget, planning and main risks, etc. Finally the plan needs to be validated and agreed upon (and the necessary resources and budget made available) to initiate the start-up and the execution phase(s) of the project.', true, 'High', null, '''Project charter OR project management plan'' - artefact offered, not mandated.', '22 Integrated planning', 3, 'APM (published)', 113),
  ('4.5.10.2', '4.5.10', 'Initiate and manage the transition to a new project phase', 'Following the decision to fund and continue with the project, the start-up of the next phase and all subsequent phases are all carried out with the following in mind: • The specific objectives for this next phase of the project; • Any necessary organisational changes; • The need to reconfirm or modify the project charter and project management plans. The detailed time schedule, cost and resource plans, risk register and possibly the expected benefits (business case) all need to be updated. Depending on the size or complexity of the project, a kick-off meeting is an effective means to inform and engage the project team(s) about the plans, demands and goals of the proj-ect or project phase. This meeting or workshop may also be used to define the work breakdown, planning, assignments or project values in more detail.', true, 'High', null, null, '22 Integrated planning', 3, 'APM (published)', 114),
  ('4.5.10.3', '4.5.10', 'Control project performance against the project plan and take any necessary remedial actions', 'Control is based on project objectives, plans and contracts. This management process measures actual project progress and performance, compares it against the baseline, and takes any necessaryremedial action. Controlling is normally done through checks against pre-set objectives by measuring results and cor-recting deviations (diagnostic control). When there are major uncertainties, these can be reduced by using feedback and suggestions from operational mem-bers to adjust the process (interactive control). Control and reporting is carried out for the current period and includes a forecast for an appropriate number of future time periods. An integrated project controlling and reporting system covers all project objectives and the corresponding success criteria for the relevant project phases and requirements of all stakeholders. Practice 163', true, 'High', null, null, '22 Integrated planning', 3, 'APM (published)', 115),
  ('4.5.10.4', '4.5.10', 'Report on project progress', 'Reporting provides information and communication about the status of work on the project (cost, time, resources, risks and opportunities, exceptions, etc) in the current and previous phases, and forecasts developments for the current phase and up until the end of the project. Reporting includes both periodic verbal and written status updates and forecasts by team members or team leads to the project manager and by the project manager to stakeholders, such as the principal and project boards. Reporting also includes financial audits and reviews of the project. Where the individual and/or team are very experienced, it may be sufficient and acceptable for stakeholders to ‘report only by exception’. This means only issuing a report when there is something significant that needs to be reported, rather than being monitored via regular status or update reports.', true, 'High', null, null, '22 Integrated planning', 3, 'APM (published)', 116),
  ('4.5.10.5', '4.5.10', 'Assess, get agreement on and implement project changes', 'Changes are often necessary in a project due to unanticipated occurrences. It may be necessary to change the project specification or the contract terms with suppliers or customers. Changes must be monitored against the original project goals and objectives as set out in the business case and/or project charter. At the start of a project, the change management process to be adopted should be agreed with all relevant stakeholders. A formal, proactive change management process that anticipates the need for change is preferable to a process that only reacts after the need for change is obvious. A change to the scope of a project or to the specification of a deliverable is made by a formal, predefined process. The change process embraces everything that results from the change required or new opportunity identified. It includes agreement on the change decision process, agreement on the need for change and the decision to accept the change and its implementation. This applies for all kinds of changes. Change management identifies, describes, classifies, assesses, approves or rejects, realises and verifies changes against legal and other agree-ments. Changes can be requested by any party and have to be managed as both proposed and approved changes, as well as properly communicated to all rele-vant stakeholders. For the management of a change, its direct and indirect effects on the whole project and its context are taken into account. The impact of the changes on the project deliverables, configuration, time schedule, cost, finance plan and risks are determined by comparison with the project baseline. Once the changes have been accepted, the project plan is adjusted accordingly.', true, 'High', null, 'Distinct from 4.5.3.4: that maintains scope configuration continuously, this runs the formal change process.', '29 Change control', 3, 'APM (published)', 117),
  ('4.5.10.6', '4.5.10', 'Close and evaluate a phase or the project', 'The close-out process takes place after the completion of the project or of a phase of the project, after the results of the project or phase have been delivered. Each phase of a project or sub-project should be formally closed with an evalua-tion and documentation of the phase carried out, checking that objectives have been achieved and customer expectations met. In the close-out of a phase, the proposals for the next phase(s) of the project should be reviewed and any issues requiring a decision submitted to the appropriate body for authorisation. Where a formal contract has been signed, considerations include transfer of responsibilities from the contractor to the project owner, the commencement of the warranty period and the final payments that need to be invoiced. Handover (also known as ‘as built’) documentation needs to be produced and training pro-vided to those who will use the project results. These are essential to ensure that the benefits of the investment made in the project are realised. Project results and experience gained are evaluated and lessons learned are documented so that they can be used to improve future projects. The members of the project team will be required for new assignments and should be formally released from their roles and responsibilities. Practice 165', true, 'High', null, 'Lessons-learned cluster - close-out artefact instance.', '8 Reviews', 3, 'APM (published)', 118),
  ('4.5.11.1', '4.5.11', 'Develop and implement a risk management framework', 'The individual designs, develops and implements a risk management framework in order to ensure that risks and opportunities are managed consistently and systematically throughout the project lifecycle. The risk management frame-work should include the definition of the methods to be used to identify, cate-gorise, evaluate, assess and treat risks and should link to the organisation’s risk management policy and international, national or industry standards. When projects are part of a programme or portfolio, the risk management framework also describes who is responsible for handling which risks and opportunities and what kind of escalation paths there are (upwards, downwards, sideways).', true, 'High', null, 'Phase 2: KIB has a risk framework; PMs apply rather than develop it - address in guidance.', '28 Risk and issue management', 3, 'APM (published)', 119),
  ('4.5.11.2', '4.5.11', 'Identify risks and opportunities', 'The individual is responsible for the ongoing task of identifying all sources of risks and opportunities and involving others in this process. There are various sources of risks and opportunities, both internal to the project and external. The individual can make use of various techniques and sources to identify risks and opportunities (e.g. from lessons learned, literature, risk and opportunity breakdown structures and interactive sessions with team members, stakehold-ers and subject matter experts). The identification process is not only about identifying risks, but also about opportunities that could, for instance, make the deliverables cheaper, or make the project run faster, less prone to risks or simply better from a quality perspective. Because the influences coming from the environment of the project do change over time, risk and opportunity iden-tification should be a continuous and ongoing process.', true, 'High', null, null, '28 Risk and issue management', 3, 'APM (published)', 120),
  ('4.5.11.3', '4.5.11', 'Assess the probability and impact of risks and opportunities', 'The individual is responsible for the ongoing task of assessing identified risks and opportunities. Risk and opportunity assessment can be done qualitatively and quantitatively. The best approach is to do both and to regularly re-assess both risks and opportunities. The qualitative assessment could cover a more in-depth analysis of the sources behind identified risks and/or opportunities; it also deals with conditions and impacts. An example is scenario planning. The quantitative assessment deals with probabilities and estimates and it also translates probabilistic impacts into quantifiable measures. Quantitative assessment provides numerical values measuring probability and impact expected from risks and opportunities. Monte Carlo analysis and decision trees are examples of powerful quantitative risk assessment techniques.', true, 'High', null, 'Phase 2: Monte Carlo and decision-tree measures are specialist techniques - address in guidance.', '28 Risk and issue management', 3, 'APM (published)', 121),
  ('4.5.11.4', '4.5.11', 'Select strategies and implement response plans to address risks and opportunities', 'The individual is responsible for the ongoing process of selecting and implement-ing optimal responses to any identified risk or opportunity. This process entails assessing various possible types of responses and finally selecting the ones that are optimal or most appropriate. For each risk the response options may include: • Avoiding the risk by deciding not to start or continue with the activity that gives rise to the risk; • Accepting or increasing the risk in order to pursue an opportunity; • Removing the risk cause; • Changing the likelihood; • Changing the consequences; • Sharing the risk with another party or parties (including contracts and risk financing) • Accepting the risk by informed decision; • Preparing and implementing a contingency plan. Similar response options apply to opportunities: • Eliminating the uncertainty by making the opportunity definitely happen (exploit); • Allocating ownership to a third party who is best able to handle it (share); • Increasing probability and/or impact, by identifying and maximising key opportunity drivers (enhance); • Taking no special measures to address the opportunity (ignore). Those risks that are not acceptable and those opportunities that are to be pursued require an appropriate response plan. Often, even after implementing risk responses, there is a residual risk that still has to be managed.', true, 'High', null, null, '28 Risk and issue management', 3, 'APM (published)', 122),
  ('4.5.11.5', '4.5.11', 'Evaluate and monitor risks, opportunities and implemented responses', 'After the appropriate risk and opportunity responses have been implemented (this may include appointing risk owners for certain or all risks) the risks and opportuni-ties will need to be monitored. The risks and opportunities and the appropriateness of the selected responses should be re-assessed periodically. Risk and opportunity probabilities and/or impacts may change, new information may become avail-able, new risks and opportunities may arise and the responses may no longer be appropriate. The overall strategies may also need to be evaluated. In fact, risk and opportunity management is not just a periodic process, but should take place continuously as all actions may carry a risk aspect.', true, 'High', null, null, '28 Risk and issue management', 3, 'APM (published)', 123),
  ('4.5.12.1', '4.5.12', 'Identify stakeholders and analyse their interests and influence', 'The individual identifies all individuals, groups and organisations relevant to the project. The individual first has to analyse the attitudes of each stakeholder group and find out the reasons for these attitudes (the interests of the stake-holder in the project’s outcome or process). Secondly the individual needs to know the potential beneficial or harmful effect (influence) this stakeholder or group can have on the project. Their interests can come from various sources. For instance, because they may want to, or have to, use the project’s Practice 173 deliverables or because they are competing for scarce resources or budget. They can be great or small, positive or negative. In the latter case they are opposed to the project, for whatever reason. A stakeholder’s influence can also be greater or smaller and may be con-centrated in one or more areas (e.g. being able to supply or withhold funding, resources, office space and equipment, priority, access, etc). The individual should be able to make a stakeholder analysis at the beginning of each project, identifying stakeholders, their interests and influence. During the project, the individual should maintain an active analysis of the environment of the proj-ect, to identify new stakeholders, changed interests or changed influences. These changes in the stakeholder environment can be the result of changes in the project itself (e.g. going from a design to an execution phase). More often, they are the result of changes in the context of the project (e.g. organisational changes, personal changes in management, change in the economy, new regu-lations, etc). The individual should analyse the relevance of these changes for the project.', true, 'High', null, null, '13 Stakeholder engagement and communication management', 3, 'APM (published)', 124),
  ('4.5.12.2', '4.5.12', 'Develop and maintain a stakeholder strategy and communication plan', 'The individual will devise a stakeholder strategy – how to engage, keep informed, involve and commit the various stakeholders to the project and its objectives. This can be done by approaching each stakeholder, or group of stakeholders, differently, depending on their interest and influence. To make it manageable, stakeholders with similar interests and influence can be grouped together. The stakeholder strategy is often laid down in a communication plan, which describes for each stakeholder or group the why, what, when (and how often), how (through which communication channel), who (should communicate) and the level of detail of the communication. The ‘what’ is essential; the message should be tuned to the specific stakeholders’ expectations and should be aimed at committing each stakeholder to supporting (or at least not thwarting) the project. The communication plan is central to expectation management. This can be summed up as the efforts of the individual to influence the expectations of the various stakeholders so that these come to expect and appreciate what (and when) the project can and will deliver and not become disappointed because of wrongly-held expectations about progress and outcomes. Of course every communication is at least two-sided, so attention and care should be given to whether and how the sent communication was received, and follow-up should be given to feedback and other incoming communication. As circumstances change, the communication plan should be regularly revised and updated. Potential alliances are developed and potential collabo-rators are identified. The benefits and outcomes of the potential partnership or alliance are identified for all parties. A relationship is established and developed with potential collaborators.', true, 'High', null, 'Phase 2: alliances-and-partnerships measure is out of scope - address in guidance.', '13 Stakeholder engagement and communication management', 3, 'APM (published)', 125),
  ('4.5.12.3', '4.5.12', 'Engage with the executive, sponsors and higher management to gain commitment and to manage interests and expectations', 'For almost all projects the most important stakeholders include executives and sponsors. Often the executive is the supplier of funds (budget) and/or can decide on resources, priority of requirements, definition of scope, etc. With these primary stakeholders, expectation management is of the utmost importance. The commitment and confidence of the executive, higher management and/ or sponsor(s) is of great benefit both to the success of the project and that of management. A good working relationship and open communication should be established. Sometimes the roles are combined in one person, but more often different people fulfil one or more of these roles. They all have their own expectations, inter-ests and influence on the project. Depending on the project, the executive and/or sponsor(s) can play their part in the stakeholder management and act as ambassa-dors, as they often have status and connections that the individual manager lacks. Practice 175', true, 'High', null, 'Deploying a sponsor as an ambassador - sharpest differentiator in the CE for KIB.', '13 Stakeholder engagement and communication management', 3, 'APM (published)', 126),
  ('4.5.12.4', '4.5.12', 'Engage with users, partners, suppliers and other stakeholders to gain their cooperation and commitment', 'For almost all projects, early and thorough involvement of users is a prerequisite for success. Users or their representatives can provide information such as needs and requirements and how the outcome will be used. This is often essential to the definition of each deliverables. Users or user groups may also provide resources. Suppliers can provide the project with resources, knowledge, subproducts, etc. Care should be taken in choosing the best providers, especially if the knowl-edge, resources and/or sub-products can only be obtained from outside the organisation and formal contracts have to be closed to obtain these. Partners are people, groups or organisations that cooperate to jointly deliver part of the deliverables, or they may make a broader contribution to achieving project objectives. These partners may only join efforts for a specific part, or they may work together on a more permanent, alliance basis. Partners may also be other managers with whom the pace, or deliverable content, of this project has to be tuned to optimise the benefit for the organisation. When the project has a steering committee, one or more senior users or user representatives, senior suppliers or supplier representatives are part of that committee. Users and other stakeholders may be part of a sounding board that advises the executive or steering committee. The individual has to focus on these stakeholder groups from very early on in the project, and use his or her influence to select the right user representatives and suppliers.', true, 'High', null, null, '13 Stakeholder engagement and communication management', 3, 'APM (published)', 127),
  ('4.5.12.5', '4.5.12', 'Organise and maintain networks and alliances', 'As part of the stakeholder strategy, networks and alliances can be implemented. These can be both formal and informal. When they are formal, agreements are negotiated and documented and a plan for ongoing cooperation is developed and implemented. As part of this plan, performance measures are identified and an exit strategy is developed. All networks and alliances should be evaluated frequently and improved when necessary. Alliances can be ended by design, or because the formal rela-tionship is no longer beneficial to the constituent organisations or stakeholders. Often, the organisation is quite likely to want to establish alliances with the same partners for new ventures in the future, so the ending of a formal relationship needs to be handled carefully. Networks are more informal and tend to be sustained beyond the lifecycle of the project.', true, 'Low', 'Held at Low. Alliance-agreement content (negotiating and documenting alliances, exit strategies, closing contracts) describes procurement and legal work and duplicates 4.5.9.4. The informal-network half is real but narrow as written.', 'Phase 2: draft criteria around the informal-network half - building and using networks as delivery infrastructure, sustaining them beyond project close. Review with 4.4.4.2.', '13 Stakeholder engagement and communication management', 3, 'APM (published)', 128),
  ('4.5.13.1', '4.5.13', 'Assess the adaptability to change of the organisation(s)', 'Organisations and people have limited capacity, capability and willingness to change. This is influenced, among other factors, by the success of earlier changes, stress and pressure, the understood need for this particular change, culture and atmosphere and by seeing good or facing bad perspectives. There might also be resistance to the proposed change, either open or hidden, which negatively influ-ences the adaptability to change. In many cases, opposition does not come from the people who are directly affected by the change, but from those who manage them. The adaptability to change is not fixed but will be influenced by factors both inside and outside the project.', true, 'High', null, '''Takes action when the change exceeds the organisation''s capacity'' - escalation with teeth.', 'No APM equivalent', 3, 'Derived (priority rule)', 129),
  ('4.5.13.2', '4.5.13', 'Identify change requirements and transformation opportunities', 'For a business perspective-oriented projects, organisational requirements and the project’s context are analysed to determine which transformation or business change needs to occur and when. For a more societal perspective-oriented pro-ject, the analysis needs to determine which societal groups can and should be influenced by the project. This can be done by interviewing, gathering knowledge, analysis of data or using workshops. Sometimes, opportunities arise because of changes in market conditions, the project’s environment or other organisational or societal changes. Change requirements and opportunities will change regularly, so they need to be regularly reviewed and adapted.', true, 'High', null, null, 'No APM equivalent', 3, 'Derived (priority rule)', 130),
  ('4.5.13.3', '4.5.13', 'Develop change or transformation strategy', 'A change strategy is developed by the individual (or emerges and therefore is put together by the individual) to address the envisioned changes or transformations. It will be based upon the intensity and the impact of the change and takes into account the ability to change or the willingness to transform of the organisation, society or people. The timing of changes to align with organisational or societal dynamics and opportunities also needs to be considered. The plan is developed through consultation and is regularly updated. Learning, monitoring and assessing what works and what doesn’t and in which situations, is part of the strategy. Changes and transformation do not happen overnight, but usually take a while before value is added. When changes or transformations are more consequential, a stepwise approach is developed so that early successes can be valued and used as incen-tives for further change. Change plans can sometimes be planned and structured, but can also be focused on group behaviours, on power, on learning, on emer-gence. There is no one right way to do change, but the individual needs to antici-pate the change.', true, 'Medium', 'Documenting a change plan, developing a stepwise approach and adapting it are PM work. Identifying societal, organisational and personal change strategies reaches beyond a bank project - change strategy is shaped with the business owner and, for anything substantial, with Strategy and HR.', null, 'No APM equivalent', 2, 'Derived (priority rule)', 131),
  ('4.5.13.4', '4.5.13', 'Implement change or transformation management strategy Version 4.0 www.ipma.world ® MOVING FORWARD The International Project Management Association Version 4.0.1 Project, programme and portfolio managers face larger, more complex challenges today than ever before. From manufacturing and construction to information technology, pharmaceuticals, and space exploration, to mention a few, the need', 'Based on the change strategy, a set of possible interventions is planned. These might include work-shops, training, information sessions, pilots, serious games and visioning, but there will also certainly be interventions to be made regarding power and influence and handling resistance. Once a change is made, measures should be taken to sustain the change and to help organisations and individuals to avoid falling back into old behaviour.', true, 'Medium', 'Designing and implementing interventions, leading workshops and addressing resistance are PM work. ''Mass media interventions'' has no application at KIB, and the sustainment measures assume the PM is still present after project close, which ICB4 itself says is usually not the case.', null, 'No APM equivalent', 2, 'Derived (priority rule)', 132)
) as v(code, ce_code, indicator, description, active, priority, reason,
       kib_note, apm_competence, target_level, target_source, sort)
where f.name = 'IPMA ICB4' and f.version = 'v4.0.1' and ce.code = v.ce_code;

