-- verification: these must match the T0 extraction exactly -----------------
do $$
declare c_all int; c_active int; c_ce int; c_area int; c_meas int; c_lvl int;
begin
  select count(*) into c_all    from public.control;
  select count(*) into c_active from public.control where active;
  select count(*) into c_ce     from public.competence_element;
  select count(*) into c_area   from public.competence_area;
  select count(*) into c_meas   from public.measure;
  select count(*) into c_lvl    from public.scale_level;
  if c_all <> 133 then raise exception 'controls: got %, expected 133', c_all; end if;
  if c_active <> 132 then raise exception 'active controls: got %, expected 132', c_active; end if;
  if c_ce <> 28 then raise exception 'elements: got %, expected 28', c_ce; end if;
  if c_area <> 3 then raise exception 'areas: got %, expected 3', c_area; end if;
  if c_meas <> 586 then raise exception 'measures: got %, expected 586', c_meas; end if;
  if c_lvl <> 6 then raise exception 'scale levels: got %, expected 6', c_lvl; end if;
  raise notice 'Seed verified: % controls (% active), % elements, % measures.', c_all, c_active, c_ce, c_meas;
end $$;

commit;
